const DATA=unpackCat(JSON.parse(CAT_SRC));
const $=s=>document.querySelector(s);


const CUR_INFO={GBP:["en-GB","£"],USD:["en-US","$"],EUR:["de-DE","€"],INR:["en-IN","₹"],
  AUD:["en-AU","A$"],CAD:["en-CA","C$"],JPY:["ja-JP","¥"],SGD:["en-SG","S$"],
  HKD:["en-HK","HK$"],CNY:["zh-CN","¥"],AED:["en-AE","AED"],BRL:["pt-BR","R$"],
  MXN:["es-MX","MX$"],ZAR:["en-ZA","R"],NZD:["en-NZ","NZ$"],CHF:["de-CH","CHF"],
  SEK:["sv-SE","kr"],PLN:["pl-PL","zł"],THB:["th-TH","฿"],MYR:["ms-MY","RM"],
  PHP:["en-PH","₱"]};
let CUR="GBP";
try{ const c=localStorage.getItem("mgt-cur"); if(c && RATES.rates[c]) CUR=c; }catch(_){}
function rateFor(c){ return (RATES.rates && RATES.rates[c]) || 1; }


function money(v, from){
  if(v==null) return "—";
  const src = from || RATES.base;
  const inBase = src===RATES.base ? v : v/rateFor(src);
  const out = inBase * rateFor(CUR);
  const [loc] = CUR_INFO[CUR] || ["en-GB"];
  const zero = CUR==="JPY";
  try{
    return out.toLocaleString(loc,{style:"currency",currency:CUR,
      minimumFractionDigits:zero?0:2,maximumFractionDigits:zero?0:2});
  }catch(e){
    return (CUR_INFO[CUR]?CUR_INFO[CUR][1]:CUR+" ")+out.toFixed(zero?0:2);
  }
}
 
function shopMoney(v, cur){
  const c = cur || "GBP";
  const [loc] = CUR_INFO[c] || ["en-GB"];
  try{ return v.toLocaleString(loc,{style:"currency",currency:c,
        minimumFractionDigits:2,maximumFractionDigits:2}); }
  catch(e){ return c+" "+v.toFixed(2); }
}
const gbp=money;                       



const MONEY_KEY  = "m164-money-private";


const MONEY_MASK = "\u2022\u2022\u2022\u2022\u2022\u2022";
let moneyHidden = false;


try{ moneyHidden = localStorage.getItem(MONEY_KEY) === "1"; }catch(_){}


try{
  if(typeof SUPA === "object" && SUPA && localStorage.getItem("m164-session")) moneyHidden = true;
}catch(_){}


function priv(v, from){ return moneyHidden ? MONEY_MASK : money(v, from); }
 
function privAmt(s){ return moneyHidden ? MONEY_MASK : s; }


function privIf(s, instead){ return moneyHidden ? (instead || "") : s; }
function moneyIsPrivate(){ return moneyHidden; }



function savePref(k, v){
  if(typeof window.setPref === "function"){ window.setPref(k, v); return; }
  try{ localStorage.setItem(k, v); }catch(_){}
}



 


function heldBack(d){
  return !!d && !!d.hid && !(d.o || d.w || d.q || d.pd || d.user);
}
function isRelease(d){ return !!d && !d.k && !d.xc && !heldBack(d); }


var _held164 = null;
function forget164(){ _held164 = null; }
function launch164(){
  if(_held164 === null) _held164 = DATA.some(d => d.hid);
  return _held164;
}
function isOwned(d){ return !!d && d.o === 1 && isRelease(d); }
function isIncoming(d){ return !!d && d.o === 2 && isRelease(d); }
function isCommitted(d){ return isOwned(d) || isIncoming(d); }
 
function piecesIn(list){ return list.reduce((s, d) => s + qtyOf(d), 0); }



function priceSource(d){
  if(!d || !paidOf(d)) return "none";
  

  if(d.pdk === "retail") return "retail";
  if(d.src === "RRP") return "retail";
  if(typeof RRP === "object" && RRP && RRP[d.n]) return "retail";
  return "receipt";
}
 
function paidReceipt(d){ return priceSource(d) === "receipt" ? paidOf(d) : 0; }
 
function paidRetail(d){ return priceSource(d) === "retail" ? paidOf(d) : 0; }



function ownedIn(list){ return (list || DATA).filter(isOwned); }
function incomingIn(list){ return (list || DATA).filter(isIncoming); }
function releasesIn(list){ return (list || DATA).filter(isRelease); }


function totalPaidOwned(list){ return ownedIn(list).reduce((s, d) => s + paidReceipt(d), 0); }
function totalPaidIncoming(list){ return incomingIn(list).reduce((s, d) => s + paidReceipt(d), 0); }
function totalRetailStandIn(list){ return ownedIn(list).reduce((s, d) => s + paidRetail(d), 0); }
function receiptCount(list){ return ownedIn(list).filter(d => paidReceipt(d) > 0).length; }
function retailCount(list){ return ownedIn(list).filter(d => paidRetail(d) > 0).length; }
function noPriceCount(list){ return ownedIn(list).filter(d => !paidOf(d)).length; }


let view="all", q="", marque="", sort="num", relOnly=false, chaseOnly=false, chaseMade=false, chaseHunt=false, showCanc=false, line="__all";
let brand="Mini GT";   


var PIN_KEY = "m164-pins";
var PIN_DEFAULT = ["Mini GT", "BBR", "Tarmac Works"];
let collabOnly=false;  




var scalePick = new Set();


var scaleShowAll = false;


let noPreowned=false, noBoxes=false;
let excGroup="";     

let total,ownedA,onordA,mine,owned,onord,buyable,sealed,totVal,totPaid,withPaid,paidVal,dupA,dupes,dupeCopies;
function recount(){
  

  const P=DATA.filter(d=>inLine(d) && !heldBack(d));
  
  
  
  

  const C=[];
  ownedA=[]; onordA=[]; mine=[]; dupA=[]; withPaid=[];
  buyable=0; sealed=0; dupeCopies=0; totVal=0; totPaid=0; paidVal=0;
  

  let nChaseHeld=0, nChaseMade=0, nCancelled=0, nCollab=0;
  for(const d of P){
    
    if(d.sh.length && !d.o) buyable++;
    if(copiesOf(d).some(c=>/chase/i.test(c.x||""))) nChaseHeld++;
    if(d.chase) nChaseMade++;
    if(d.xc) nCancelled++;
    if(d.cb || brandsOf(d).length>1) nCollab++;
    if(d.k || d.xc) continue;
    C.push(d);
    if(d.o===1) ownedA.push(d);
    else if(d.o===2) onordA.push(d);
    if(d.c==="SEALED") sealed++;
    

    const q=qtyOf(d);
    if(q>1){ dupA.push(d); dupeCopies+=q-1; }
    

    if(!isOwned(d)) continue;
    mine.push(d);
    const v=valOf(d);
    totVal+=v;
    

    

    const pd=paidReceipt(d);
    if(pd>0){ withPaid.push(d); paidVal+=v; totPaid+=pd; }
  }
  total=C.length;
  owned=ownedA.length; onord=onordA.length;
  dupes=dupA.length;
  

  const scope = line!=="__all" ? line : (brand!=="__all" ? brand : "");
  

  const official = !!scope && (typeof OFFICIAL_RANGES === "object" && OFFICIAL_RANGES)
                   && OFFICIAL_RANGES.indexOf(scope) > -1;
  const hasCat = C.some(d=>!d.o);          
  

  const completable = (!!scope && (official || hasCat)) || (line==="__all" && brand==="__all" && hasCat);
  $("#kpis").innerHTML=[
    ["",line==="__all"?"Models tracked":(completable?"Catalogue":"In your collection"),
        (completable||line==="__all")?total.toLocaleString():owned],
    ["own","Owned",owned],["ord","On order",onord],
    ["buy","Buyable now",buyable],
    ["dup","Duplicates",dupes],
    ["","Value",priv(totVal)]
  ].filter(([k])=>k!=="dup"||dupes>0).map(([k,l,v])=>{
      const tab={own:"own",ord:"order",buy:"buy",dup:"dupe"}[k] || (l==="Value"?"value":"");
      return `<div class="kpi ${k}${tab?" tap":""}"${tab?` data-tab="${tab}" role="button" tabindex="0" title="Show them"`:""}><b>${v}</b><i>${l}</i></div>`;
    }).join("");
  

  KPI_DEFAULT=$("#kpis").innerHTML;
  if(typeof destKpis==="function"){ const h=destKpis(); if(h) $("#kpis").innerHTML=h; }
  

  $("#kpis").onclick = e => {
    const k=e.target.closest(".kpi.tap"); if(!k) return;
    const t=k.dataset.tab;
    const btn=$("#tabs").querySelector(`[data-v="${t}"]`);
    if(!btn) return;
    [...$("#tabs").children].forEach(x=>x.classList.toggle("on",x===btn));
    view=t; render(); window.scrollTo({top:0,behavior:"smooth"});
  };
  $("#kpis").onkeydown = e => { if(e.key==="Enter"||e.key===" "){ const k=e.target.closest(".kpi.tap"); if(k){ e.preventDefault(); k.click(); } } };
  

  const dupBtn = $("#tabs") && $("#tabs").querySelector('[data-v="dupe"]');
  if(dupBtn){
    dupBtn.hidden = dupes===0;
    if(dupes===0 && view==="dupe"){
      view="all";
      [...$("#tabs").children].forEach(x=>x.classList.toggle("on",x.dataset.v==="all"));
    }
  }
  const bar=document.querySelector("#pa")?.parentNode?.parentNode;
  if(completable){
    if(bar) bar.style.display="";
    $("#pa").style.width=owned/total*100+"%"; $("#pb").style.width=onord/total*100+"%";
    

    $("#ppct").textContent=(owned/total*100).toFixed(1)
      + (official ? "% complete" : !scope ? "% of everything on file" : "% of the list")
      + (onord?` \u00b7 ${((owned+onord)/total*100).toFixed(1)}% with what is on the way`:"");
    const head = `${owned} owned${onord?" + "+onord+" on the way":""}, of ${total.toLocaleString()}`;
    $("#ptext").textContent = !scope
      ? head + ` cars on file across every catalogue. A car in two catalogues is counted once here, so this is fewer than the catalogues added together.`
      : official
      

      ? head + ` in the manufacturer's catalogue`
        

        + ((typeof gapsFor==="function" && gapsFor(scope)
            && !(typeof collects === "object" && collects && collects.size))
           ? `. ${gapsFor(scope)} numbers in the sequence were never issued, so they are gaps in the numbering, not cars you are missing.` : "")
      

      

      

      : isCross(scope)
      ? head + ` releases ${brand} put its name on with ${crossMaker(scope)}. They carry ${crossMaker(scope)}'s number and sit in its range; ${brand} is on the box too, so they are here as well. One release, counted once overall.`
      : (line==="__all" && COMPILED["#"+scope])
      ? head + ` ${scope} ` + COMPILED["#"+scope]
      : COMPILED[scope]
      ? head + ` ${scope} ` + COMPILED[scope]
      : head + ` ${scope} models your shops list. ${scope} publishes no full back catalogue, so this is what is findable, not everything ever made.`;
  }else{
    $("#pa").style.width="0%"; $("#pb").style.width="0%";
    $("#ppct").textContent="no completion target";
    $("#ptext").textContent = scope===""
      ? `${owned} owned + ${onord} on the way across every catalogue, worth about ${priv(totVal)}. Each car is counted once here however many catalogues it belongs to. Pick a catalogue above for a completion figure.`
      : isCross(scope)
      ? `${owned} of the releases ${brand} put its name on with ${crossMaker(scope)}, worth about ${priv(totVal)}.`
      : `${owned} models, worth about ${priv(totVal)}. These lines have no published catalogue, so there is no honest percentage to show.`;
  }
  

  paintScopeChrome();
  if(typeof paintNav==="function"){ paintNav(); paintDrawerCard(); paintHero();
 
queuePhotos(); }
   
  const chip=$("#chaseonly");
  if(chip){ chip.textContent = nChaseHeld ? `Chases you hold (${nChaseHeld})` : "Chases you hold";
            chip.style.opacity = nChaseHeld ? "" : ".45"; }
  const ct=$("#canctoggle");
  if(ct){ ct.style.display = nCancelled?"":"none"; ct.textContent = `Cancelled (${nCancelled})`; }
  const ce=$("#chaseexists");
  if(ce){ ce.textContent = nChaseMade ? `Has a chase (${nChaseMade})` : "Has a chase";
          ce.style.opacity = nChaseMade ? "" : ".45"; }
  const cc=$("#collabonly");
  if(cc){ cc.style.display = nCollab ? "" : "none";
          cc.textContent = `Collaborations (${nCollab})`; }
}

const SHOPN=new Set(DATA.flatMap(d=>(d.sh||[]).map(s=>s[0]))).size;   






const LINES=["Mini GT","Kaidohouse","QubeCarz","Accessories","OEM","BBR"];





const _brandsCache = new WeakMap();
function brandsOf(d){
  if(d && typeof d === "object"){
    const hit = _brandsCache.get(d);
    if(hit && hit.bs === d.bs && hit.br === d.br) return hit.v;
  }
  

  const b=d&&d.bs;
  let out;
  if(Array.isArray(b)){
    const clean=b.filter(x=>typeof x==="string" && x.trim()).map(x=>x.trim());
    if(clean.length) out=[...new Set(clean)];
  }
  if(!out) out=[ (d && typeof d.br==="string" && d.br.trim()) || "Other" ];
  if(d && typeof d === "object") _brandsCache.set(d, {bs:d.bs, br:d.br, v:out});
  return out;
}




let BRANDS=[];
function refreshBrands(){
  const c={};
  DATA.forEach(d=>{ if(heldBack(d)) return;
                    brandsOf(d).forEach(b=>{ c[b]=(c[b]||0)+1; }); });
  

  const pin = (typeof pinnedBrands === "function") ? pinnedBrands() : [];
  const rank = b => { const i = pin.indexOf(b); return i < 0 ? pin.length : i; };
  BRANDS=Object.keys(c).sort((a,b)=> rank(a)-rank(b) || a.localeCompare(b));
  if(brand!=="__all" && BRANDS.indexOf(brand)<0) brand = BRANDS[0] || "__all";
  return BRANDS;
}
refreshBrands();


