if(typeof LINE_ORDER === "undefined" || !Array.isArray(LINE_ORDER) || !LINE_ORDER.length)
  var LINE_ORDER=[...LINES,...TW_LINES,...PR_LINES,...SP_LINES,...HW_LINES,
                  ...B6_LINES,...TOMICA_LINES,...IXO_LINES];
function inBrand(d){ return brand==="__all" || brandsOf(d).indexOf(brand)>-1; }




const CROSS_PREFIX = "__cross:";
const CROSS_LINE = CROSS_PREFIX;              
function isCross(l){ return typeof l === "string" && l.indexOf(CROSS_PREFIX) === 0; }
function crossMaker(l){ return isCross(l) ? l.slice(CROSS_PREFIX.length) : ""; }
function rangeIsForeign(d){
  if(brand === "__all") return false;
  const owner = (typeof RANGE_OWNER === "object" && RANGE_OWNER) ? RANGE_OWNER[d.br] : null;
  return !!owner && owner !== brand;
}
function lineKeyOf(d){
  return rangeIsForeign(d) ? CROSS_PREFIX + RANGE_OWNER[d.br] : d.br;
}


let collects = new Set();





const ISS_SAYS = {
  L:   ["Left-hand drive",   "the left-hand drive issue of this release", 1],
  R:   ["Right-hand drive",  "the right-hand drive issue of this release", 1],
  MJ:  ["Mijo issue",        "also issued in a Mijo blister for the American market"],
  TRU: ["Toys\u2019R\u2019Us issue", "also issued for Toys\u2019R\u2019Us"],
  LB:  ["LBWK black card",   "also issued on the LBWK black card"],
  BL:  ["Blister issue",     "also issued on a blister card rather than in a box"],
  CH:  ["Chase issue",       "the chase version of this release"],
  AEON:["AEON issue",        "also issued for AEON"],
  SP:  ["Special issue",     "a special issue of this release"],
  D1:  ["D1 issue",          "issued for D1"],
  LM:  ["Le Mans issue",     "issued for Le Mans"]
};

 
const COLLECT_FLAGS = [
  {k:"bond",  lab:"007",                test:d=>!!d.bond,
   why:"released under the James Bond licence"},
  

  {k:"ex",    lab:"Exclusives",         test:d=>!!d.ex,
   why:"sold only in one market, or at one event, or through one shop"},
  {k:"prem",  lab:"Premium",            test:d=>!!d.hwprem,
   why:"the maker's premium line rather than its mainline"},
  {k:"tuner", lab:"Tuner or livery",    test:d=>!!d.tn,
   why:"wears a tuner's kit or a named livery"},
  {k:"ms",    lab:"Motorsport",         test:d=>!!d.ms,
   why:"a model of a particular car that raced"},
  

  {k:"nocode",lab:"Number unconfirmed", test:d=>!!d.nocode, minor:1,
   why:"no maker prints a number for this one, so none is claimed"}
];



const COLLECT_VALUE = [
  {p:"reg",  lab:v=>v,            group:"Sold only in",
   of:d=>(d.ex && d.ex.c && d.ex.c !== "?") ? d.ex.c : null, cap:40,
   why:v=>"sold only in " + v},
  {p:"tn",   lab:v=>v,            group:"Tuner or livery",
   of:d=>d.tn || null, cap:24, least:4,
   why:v=>"wears " + v},
  {p:"pack", lab:v=>v,            group:"Packaging",
   of:d=>d.pack || null, cap:8,
   why:v=>"comes in a " + String(v).toLowerCase()},
  

  {p:"fam",  lab:v=>v,            group:() => taxLabelHere("fam", "Family"),
   of:d=>d.fam || null, cap:20,
   why:v=>"part of " + v},
  

  {p:"msser", lab:v=>v,           group:"Raced in",
   of:d=>(d.ms && d.ms.series) || null, cap:26, least:3,
   why:v=>"raced in " + v},
  {p:"msev",  lab:v=>v,           group:"Raced at",
   of:d=>(d.ms && d.ms.event) || null, cap:32, least:4,
   why:v=>"a car that ran at " + v}
];





let _colCache = {sig:"", out:null};
function collectionsHere(){
  const sig = brand + "|" + line + "|" + DATA.length;
  if(_colCache.sig === sig && _colCache.out) return _colCache.out;
  const out = [], n = {}, brOf = {};
  const note = (k, d) => {
    n[k] = (n[k] || 0) + 1;
    const seen = brOf[k] || (brOf[k] = {});
    seen[d.br] = 1;
  };
  let total = 0;
  const ranges = {};
  for(const d of DATA){
    if(!inBrand(d) || !inLineOnly(d) || heldBack(d)) continue;
    total++;
    ranges[d.br] = (ranges[d.br] || 0) + 1;
    for(const f of COLLECT_FLAGS) if(f.test(d)) note(f.k, d);
    for(const i of (d.iss || [])) if(i && i.s) note("iss:" + i.s, d);
    for(const v of COLLECT_VALUE){
      const got = v.of(d);
      if(got != null && got !== "") note(v.p + ":" + got, d);
    }
  }
  if(!total){ _colCache = {sig, out:[]}; return _colCache.out; }
  for(const f of COLLECT_FLAGS)
    if(n[f.k]) out.push({k:f.k, lab:f.lab, n:n[f.k], why:f.why, group:"", minor:f.minor||0});
  for(const k of Object.keys(n)){
    if(k.indexOf("iss:") !== 0) continue;
    const code = k.slice(4);
    const say = ISS_SAYS[code] || [code + " issue", "issue code " + code + ", as the maker prints it"];
    out.push({k, lab:say[0], n:n[k], why:say[1], group:"Issued as", minor:say[2] || 0});
  }
  for(const v of COLLECT_VALUE){
    

    const mine = Object.keys(n).filter(k => k.indexOf(v.p + ":") === 0
                                            && !(v.least && n[k] < v.least));
    if(!mine.length || mine.length > v.cap) continue;
    for(const k of mine){
      const val = k.slice(v.p.length + 1);
      

      out.push({k, lab:v.lab(val), n:n[k], why:v.why(val),
                group: (typeof v.group === "function") ? v.group() : v.group, minor:0});
    }
  }
  

  const sameAsRange = c => {
    const seen = Object.keys(brOf[c.k] || {});
    return seen.length === 1 && ranges[seen[0]] === c.n;
  };
  _colCache = {sig, out: out.filter(c => c.n < total && !sameAsRange(c))};
  return _colCache.out;
}
function forgetCollections(){ _colCache = {sig:"", out:null}; }



function matchesCollection(d, k){
  if(k.indexOf("iss:") === 0){
    const code = k.slice(4);
    return (d.iss || []).some(i => i && i.s === code);
  }
  const at = k.indexOf(":");
  if(at > 0){
    const p = k.slice(0, at), val = k.slice(at + 1);
    const def = COLLECT_VALUE.find(v => v.p === p);
    return !!def && String(def.of(d)) === val;
  }
  const f = COLLECT_FLAGS.find(x => x.k === k);
  return !!f && f.test(d);
}
function inCollections(d){
  if(!collects.size) return true;
  for(const k of collects) if(!matchesCollection(d, k)) return false;
  return true;
}
function clearCollections(){
  if(!collects.size) return false;
  collects = new Set();
  return true;
}



function fillCollectionSheet(){
  const host = document.getElementById("collectall");
  if(!host) return;
  const list = collectionsHere();
  const keys = new Set(list.map(c => c.k));
  for(const k of collects) if(!keys.has(k)) list.push({k, lab:collectionLabel(k), n:0, why:"", group:""});
  if(!list.length){ host.innerHTML = '<span class="hint">Nothing in this catalogue to group by yet.</span>'; return; }
  const groups = [];
  for(const c of list){
    let g = groups.find(x => x.name === (c.group || ""));
    if(!g) groups.push(g = {name:c.group || "", items:[]});
    g.items.push(c);
  }
  groups.sort((a, b) => (a.name ? 1 : 0) - (b.name ? 1 : 0) || a.name.localeCompare(b.name));
  host.innerHTML = groups.map(g =>
    (g.name ? `<span class="fl cgrp">${esc(g.name)}</span>` : "")
    + g.items.sort((a,b) => (a.minor||0) - (b.minor||0) || (b.n - a.n) || a.lab.localeCompare(b.lab)).map(c =>
        `<button type="button" class="chip" aria-pressed="${collects.has(c.k)}"`
        + ` data-col="${esc(c.k)}" title="${esc(c.why || c.lab)}">`
        + `${esc(c.lab)} <i>${c.n}</i></button>`).join("")
  ).join("");
}



var rarPick = new Set();
function rarCountsHere(){
  

  const keep = rarPick; let c = {}, none = 0;
  try{
    rarPick = new Set();
    for(const d of subset()){
      if(d.rr == null){ none++; continue; }
      const b = rarBand(d.rr); c[b] = (c[b] || 0) + 1;
    }
  } finally { rarPick = keep; }
  return { bands: c, none };
}
function fillRarity(){
  const row = document.getElementById("rarrow"), lab = document.getElementById("rarlab");
  if(!row) return;
  const { bands, none } = rarCountsHere();
  const any = Object.keys(bands).length > 0;
  if(!any){
    row.innerHTML = ""; row.hidden = true; if(lab) lab.hidden = true; return;
  }
  row.hidden = false; if(lab) lab.hidden = false;
  const btn = (k, label, n, title) =>
    `<button type="button" class="chip${rarPick.has(k) ? " on" : ""}" data-rar="${esc(k)}"
      aria-pressed="${rarPick.has(k)}" title="${esc(title)}">${esc(label)} <b>${n}</b></button>`;
  row.innerHTML =
    RAR_BANDS.filter(b => bands[b]).map(b =>
      btn(b, b, bands[b], "how scarce the release is, not what it is worth")).join("")
    + (none ? btn("__none", "Not established", none,
        "no evidence on file about how scarce these are. Not a low score: no score.") : "");
}
document.getElementById("rarrow").onclick = e => {
  const b = e.target.closest("button[data-rar]"); if(!b) return;
  const k = b.dataset.rar;
  rarPick.has(k) ? rarPick.delete(k) : rarPick.add(k);
  fillRarity(); recount(); render(); paintFilters();
};
function inRarity(d){
  if(!rarPick.size) return true;
  if(d.rr == null) return rarPick.has("__none");
  return rarPick.has(rarBand(d.rr));
}



const TAX_FALLBACK = [{k:"br",lab:"Range"},{k:"fam",lab:"Series"}];
function taxLevels(maker){
  const T = (typeof TAXONOMY === "object" && TAXONOMY) ? TAXONOMY : {};
  const D_ = (typeof TAX_DEFAULT !== "undefined" && TAX_DEFAULT) ? TAX_DEFAULT : TAX_FALLBACK;
  return (maker && T[maker]) || D_;
}
function taxLabel(maker, k, fallback){
  const lv = taxLevels(maker).find(x => x.k === k);
  return lv ? lv.lab : (fallback || k);
}


function taxMaker(){ return brand === "__all" ? null : brand; }
function taxLabelHere(k, fallback){ return taxLabel(taxMaker(), k, fallback); }



function segOf(d){
  const M = (typeof HW_SEGMENT === "object" && HW_SEGMENT) ? HW_SEGMENT : {};
  return (d && M[d.br]) || null;
}
function segDef(k){
  const L = (typeof SEGMENTS !== "undefined" && Array.isArray(SEGMENTS)) ? SEGMENTS : [];
  return L.find(x => x[0] === k) || null;
}
function segName(k){ const d = segDef(k); return d ? d[1] : k; }
function segNote(k){ const d = segDef(k); return d ? d[2] : ""; }


function segWhy(br){
  const U = (typeof SEG_UNPLACED === "object" && SEG_UNPLACED) ? SEG_UNPLACED : {};
  return U[br] || "";
}
function makerHasSegments(){ return taxLevels(taxMaker()).some(l => l.k === "seg"); }

 
function attrsOf(d){ return (d && Array.isArray(d.hwa)) ? d.hwa : []; }
function attrDef(c){
  const A = (typeof TAX_ATTRS === "object" && TAX_ATTRS) ? TAX_ATTRS : {};
  return A[c] || null;
}


function attrWhy(d, c){
  const a = attrDef(c);
  if(!a) return "";
  const said = k => d && Array.isArray(d[k]) && d[k].indexOf(c) > -1;
  if(said("hwafn") && a.from_pos)    return a.from_pos;
  if(said("hwafp") && a.from_photo)  return a.from_photo;
  if(said("hwafr") && a.from_retire) return a.from_retire;
  return a.from_ || "";
}
function attrShort(c){ const a = attrDef(c); return a ? a.short : c.toUpperCase(); }
function attrName(c){ const a = attrDef(c); return a ? a.lab : c; }



function countsWithout(pick, bucket){
  const keep = [...pick]; pick.clear();
  try{
    const c = {}; let none = 0;
    for(const d of subset()){
      const ks = bucket(d);
      if(!ks || !ks.length){ none++; continue; }
      for(const k of ks) c[k] = (c[k] || 0) + 1;
    }
    return { c, none };
  } finally { keep.forEach(x => pick.add(x)); }
}
function chipRow(rowId, labId, entries, pick, none, noneLabel, noneTitle, dataKey){
  const row = document.getElementById(rowId), lab = document.getElementById(labId);
  if(!row) return;
  if(!entries.length){ row.innerHTML = ""; row.hidden = true; if(lab) lab.hidden = true; return; }
  row.hidden = false; if(lab) lab.hidden = false;
  const btn = (k, label, n, title) =>
    `<button type="button" class="chip${pick.has(k) ? " on" : ""}" data-${dataKey}="${esc(k)}"`
    + ` aria-pressed="${pick.has(k)}" title="${esc(title)}">${esc(label)} <b>${n}</b></button>`;
  row.innerHTML = entries.map(e => btn(e.k, e.lab, e.n, e.title)).join("")
    + (none ? btn("__none", noneLabel, none, noneTitle) : "");
}

var segPick = new Set(), attrPick = new Set();
function fillSegments(){
  const row = document.getElementById("segrow"), lab = document.getElementById("seglab");
  if(!row) return;
  if(!makerHasSegments()){
    segPick.clear();
    row.innerHTML = ""; row.hidden = true; if(lab) lab.hidden = true; return;
  }
  if(lab) lab.textContent = taxLabelHere("seg", "Segment");
  const { c, none } = countsWithout(segPick, d => { const k = segOf(d); return k ? [k] : []; });
  const L = (typeof SEGMENTS !== "undefined" && Array.isArray(SEGMENTS)) ? SEGMENTS : [];
  chipRow("segrow", "seglab",
    L.filter(x => c[x[0]]).map(x => ({ k: x[0], lab: x[1], n: c[x[0]], title: x[2] })),
    segPick, none, "Not placed",
    "the sources do not agree which tier these belong to, so none is claimed", "seg");
}
function fillAttrs(){
  const row = document.getElementById("attrrow"), lab = document.getElementById("attrlab");
  if(!row) return;
  const { c } = countsWithout(attrPick, attrsOf);
  const order = (typeof TAX_ATTR_ORDER !== "undefined" && Array.isArray(TAX_ATTR_ORDER))
    ? TAX_ATTR_ORDER : Object.keys(c);
  const entries = order.filter(k => c[k]).map(k => {
    const a = attrDef(k) || {};
    return { k, lab: a.lab || k, n: c[k], title: (a.note || "") + (a.from_ ? " Established because " + a.from_ + "." : "") };
  });
  if(!entries.length) attrPick.clear();
  

  chipRow("attrrow", "attrlab", entries, attrPick, 0, "", "", "attr");
}
(function(){
  const sr = document.getElementById("segrow");
  if(sr) sr.onclick = e => {
    const b = e.target.closest("button[data-seg]"); if(!b) return;
    const k = b.dataset.seg;
    segPick.has(k) ? segPick.delete(k) : segPick.add(k);
    fillSegments(); fillAttrs(); fillScales(); recount(); render(); paintFilters();
  };
  const ar = document.getElementById("attrrow");
  if(ar) ar.onclick = e => {
    const b = e.target.closest("button[data-attr]"); if(!b) return;
    const k = b.dataset.attr;
    attrPick.has(k) ? attrPick.delete(k) : attrPick.add(k);
    fillSegments(); fillAttrs(); fillScales(); recount(); render(); paintFilters();
  };
})();
function inSegment(d){
  if(!segPick.size) return true;
  const k = segOf(d);
  return k ? segPick.has(k) : segPick.has("__none");
}
function inAttrs(d){
  if(!attrPick.size) return true;
  const a = attrsOf(d);
  

  for(const k of attrPick) if(a.indexOf(k) < 0) return false;
  return true;
}



function collectionLabel(k){
  if(k.indexOf("iss:") === 0){
    const say = ISS_SAYS[k.slice(4)];
    return say ? say[0] : k.slice(4) + " issue";
  }
  const at = k.indexOf(":");
  if(at > 0){
    const def = COLLECT_VALUE.find(v => v.p === k.slice(0, at));
    return def ? def.lab(k.slice(at + 1)) : k.slice(at + 1);
  }
  const f = COLLECT_FLAGS.find(x => x.k === k);
  return f ? f.lab : k;
}

function linesOfBrand(){
  const seen=[];
  

  DATA.forEach(d=>{ if(inBrand(d) && !heldBack(d)){ const k=lineKeyOf(d); if(seen.indexOf(k)<0) seen.push(k); } });
  const order=LINE_ORDER;
  return seen.sort((a,b)=>{
     
    if(isCross(a) && isCross(b)) return crossMaker(a).localeCompare(crossMaker(b));
    if(isCross(a)) return 1;
    if(isCross(b)) return -1;
    const ia=order.indexOf(a), ib=order.indexOf(b);
    return (ia<0?99:ia)-(ib<0?99:ib) || a.localeCompare(b);
  });
}


function lineName(l){ return isCross(l) ? "\u00d7 " + crossMaker(l) : l; }
function inLineOnly(d){
  return line==="__all" ? true
       : isCross(line) ? (rangeIsForeign(d) && RANGE_OWNER[d.br] === crossMaker(line))
       : (d.br===line && !rangeIsForeign(d));
}


function inLine(d){ return inBrand(d) && inLineOnly(d) && inCollections(d) && inRarity(d) && inSegment(d) && inAttrs(d); }


function gapsFor(l){
  if(typeof NOTISSUED==="undefined" || !NOTISSUED) return 0;
  if(typeof NOTISSUED==="number") return l==="Mini GT" ? NOTISSUED : 0;
  return NOTISSUED[l] || 0;
}


const cnt=b=>DATA.filter(d=>d.br===b&&isOwned(d)).length;
const tot=b=>DATA.filter(d=>d.br===b&&isRelease(d)).length;


const bcnt=b=>DATA.filter(d=>(b==="__all"||brandsOf(d).indexOf(b)>-1)&&isOwned(d)).length;
const btot=b=>DATA.filter(d=>(b==="__all"||brandsOf(d).indexOf(b)>-1)&&isRelease(d)).length;

function fillLines(){
  const mine=linesOfBrand();
  

  const {have,all,solo,boxes}=seriesCounts();
  const lab=b=>seriesLabel(b,solo);
  

  const n=b=>(have[b]||0), t=b=>(all[b]!==undefined ? all[b] : (boxes[b]||0));
  

  const known=b=>isCross(b)||LINE_ORDER.includes(b);
  const tracked=mine.filter(known);
  const loose=mine.filter(b=>!known(b));
  const label = brand==="__all" ? "Everything — " : "All of "+brand+" — ";
  $("#line").innerHTML=
    (tracked.length ? `<optgroup label="${brand==="__all"?"In the catalogue":esc(brand)+" series"}">`
      + tracked.map(b=>`<option value="${esc(b)}">${esc(lab(b))} — ${n(b)}/${t(b)}</option>`).join("")
      + `</optgroup>` : "")
    + (loose.length ? `<optgroup label="Series you added">`
      + loose.map(b=>`<option value="${esc(b)}">${esc(lab(b))} — ${n(b)}/${t(b)}</option>`).join("")
      + `</optgroup>` : "")
    + `<optgroup label="Combined">`
    + `<option value="__all">${label}${bcnt(brand)}/${btot(brand)}</option>`
    + `</optgroup>`;
  

  const _ll = document.getElementById("linelab");
  if(_ll) _ll.textContent = taxLabelHere("br", "Range");
  

  const oneline = brand!=="__all" && mine.length<=1;
  $("#line").style.display = oneline ? "none" : "";
  

  if(line!=="__all" && mine.indexOf(line)<0) line="__all";
  $("#line").value=line;
}
$("#line").onchange=e=>{line=e.target.value; recount(); render(); if(typeof drawStats==="function") drawStats();};





function seriesCounts(){
  const have={}, all={}, solo={}, boxes={};
  for(const d of DATA){
    if(d.xc || !inBrand(d) || heldBack(d)) continue;
    const k = lineKeyOf(d);
    

    if(d.k){ boxes[k]=(boxes[k]||0)+1; continue; }
    all[k]=(all[k]||0)+1;
    if(isOwned(d)) have[k]=(have[k]||0)+1;
    if(!d.cb) solo[k]=true;
  }
  return {have,all,solo,boxes};
}


function seriesLabel(b, solo){
  return lineName(b);
}
let _linesSig="";
function paintLines(){
  const box=document.getElementById("lines"); if(!box) return;
  const {have,all,solo,boxes}=seriesCounts();
  

  const mine=[...new Set([...Object.keys(all),...Object.keys(boxes)])].sort((a,b)=>{
    const ia=LINE_ORDER.indexOf(a), ib=LINE_ORDER.indexOf(b);
    return (ia<0?99:ia)-(ib<0?99:ib) || a.localeCompare(b);
  });
  

  if(brand==="__all" || mine.length<2){
    if(!box.hidden){ box.hidden=true; box.innerHTML=""; syncStickyTops(); }
    _linesSig="";
    return;
  }
  

  const sig=[brand,line,innerWidth<=760,mine.map(b=>b+have[b]+"/"+all[b]+"+"+(boxes[b]||0)).join()].join("|");
  if(sig===_linesSig && !box.hidden) return;
  _linesSig=sig;
  const was=box.hidden;
  box.hidden=false;
  const chip=(v,name,h,t,title)=>
    `<button type="button" aria-pressed="${v===line}" data-l="${esc(v)}" class="${v===line?"on":""}"`
    + ` title="${esc(title)}">${esc(name)} <i>${h}/${t}</i></button>`;
  const allName = brand==="__all" ? "Everything"
                : (innerWidth<=760 ? "All" : "All of "+brand);
  let out=chip("__all", allName, bcnt(brand), btot(brand),
               brand==="__all" ? "Every car on file, each counted once"
                               : "Every series in "+brand);
  

  

  out+=mine.map(b=>{
    const cars=all[b], bx=boxes[b]||0;
    if(cars===undefined && bx)
      return chip(b, seriesLabel(b,solo), have[b]||0, bx,
                  b+" \u2014 "+bx+" boxes of cars. A box counts as nothing on its own; "
                  + "the cars inside it each count as one.");
    return chip(b, seriesLabel(b,solo), have[b]||0, cars,
        !isCross(b)
          ? b+" \u2014 "+(have[b]||0)+" of "+cars+" owned or on the way"
          : "Releases "+brand+" put its name on with "+crossMaker(b)+". They carry "
            +crossMaker(b)+"'s number and sit in its range, and "+brand+" is on the box "
            +"too \u2014 "+(have[b]||0)+" of "+cars+" owned or on the way");
  }).join("");
  box.innerHTML=out;
  railChrome(box);
  if(was) syncStickyTops();
}
function toggleCollection(k){
  if(collects.has(k)) collects.delete(k); else collects.add(k);
  recount(); render(); paintFilters();
  fillCollectionSheet();
  if(typeof drawStats==="function" && view==="stats") drawStats();
}
document.getElementById("collectall").onclick=e=>{
  const b=e.target.closest("button[data-col]"); if(!b) return;
  toggleCollection(b.dataset.col);
};
document.getElementById("lines").onclick=e=>{
  const b=e.target.closest("button[data-l]"); if(!b) return;
  line=b.dataset.l;
  

  const sel=document.getElementById("line");
  if(sel && [...sel.options].some(o=>o.value===line)) sel.value=line;
  recount(); render(); paintFilters();
  if(typeof drawStats==="function") drawStats();
};





const BRANDCOL={"Mini GT":"var(--b-minigt)","Kaidohouse":"var(--b-minigt)","QubeCarz":"var(--b-minigt)",
  "Accessories":"var(--b-minigt)","Tarmac Works":"var(--b-tarmac)","Pop Race":"var(--b-poprace)",
  "XCarToys":"var(--b-xcartoys)","Schuco":"var(--b-schuco)","PARA64":"var(--b-para64)","BBR":"var(--b-bbr)",
  "Hot Wheels":"var(--b-hotwheels)"};
const _hueCache = {};
function brandColourName(b){
  if(BRANDCOL[b]) return BRANDCOL[b];
  if(!b) return "var(--b-other)";
  if(_hueCache[b]) return _hueCache[b];
  let h = 0;
  for(let i = 0; i < b.length; i++) h = (h * 31 + b.charCodeAt(i)) % 360;
  

  const hue = 95 + (h % 230);
  const dark = !document.documentElement.dataset.theme
               || document.documentElement.dataset.theme === "dark";
  return (_hueCache[b] = `hsl(${hue} ${dark ? "62% 62%" : "58% 38%"})`);
}


function forgetBrandColours(){ for(const k in _hueCache) delete _hueCache[k]; }


function brandColour(d){
  if(brand!=="__all") return brandColourName(brand);
  return brandColourName(brandsOf(d)[0]);
}



let _toastT=null;


function toast(msg,kind,ms){
  const el=document.getElementById("toast"); if(!el) return;
  el.textContent=msg; el.className="toast on"+(kind?" "+kind:"");
  clearTimeout(_toastT);
  if(ms === 0) return;
  _toastT=setTimeout(()=>{ el.className="toast"+(kind?" "+kind:""); }, ms || 2200);
}
 
function untoast(){
  const el=document.getElementById("toast"); if(!el) return;
  clearTimeout(_toastT);
  el.className = el.className.replace(/\bon\b/, "").trim();
}



