let KPI_DEFAULT="";
 


function fmtMonth(ym){
  const m = String(ym||"").match(/^(\d{4})-(\d{2})$/);
  if(!m) return String(ym||"");
  const MON=["January","February","March","April","May","June","July",
             "August","September","October","November","December"];
  const i = +m[2]-1;
  return (MON[i] ? MON[i] + " " + m[1] : String(ym));
}
function fmtDate(iso){
  const m=String(iso||"").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if(!m) return esc(iso||"");
  const MON=["January","February","March","April","May","June","July",
             "August","September","October","November","December"];
  return (+m[3])+" "+MON[+m[2]-1]+" "+m[1];
}
function kpiHTML(list){
  return list.map(([k,l,v,t])=>
    `<div class="kpi ${k||""}"${t?` title="${esc(t)}"`:""}><b>${v}</b><i>${esc(l)}</i></div>`).join("");
}


function destKpis(){
  const v=curView();
  const live=d=>inLine(d)&&!d.k&&!d.xc;
  if(v==="own"||v==="order"){
    const want=v==="own"?1:2;
    const mineL=DATA.filter(d=>live(d)&&d.o===want);
    const pieces=mineL.reduce((s,d)=>s+qtyOf(d),0);
    const cats=new Set(); mineL.forEach(d=>brandsOf(d).forEach(b=>cats.add(b)));
    

    const spend   = (v==="own" ? totalPaidOwned : totalPaidIncoming)(mineL);
    const standIn = v==="own" ? totalRetailStandIn(mineL) : 0;
    const priced  = mineL.filter(d => priceSource(d) === "receipt").length;
    return kpiHTML([
      [v==="own"?"own":"ord", v==="own"?"Cars owned":"On the way", mineL.length.toLocaleString(), "unique catalogue numbers"],
      ["","Pieces", pieces.toLocaleString(), "every copy counted"],
      ["","Catalogues", cats.size, [...cats].join(", ")],
      ["","Total paid", priv(spend), "what you actually paid, not an estimate"],
      ...(standIn?[["","Priced at retail", priv(standIn),
        "cars with no receipt anywhere, priced at what they sold for new. An estimate, kept out of Total paid."]]:[]),
      ["buy","Priced", mineL.length?Math.round(priced/mineL.length*100)+"%":"—",
        priced+" of "+mineL.length+" have a receipt on file"]
    ]);
  }
  if(v==="want"){
    const w=DATA.filter(d=>live(d)&&d.w&&!d.o);
    const byw=n=>w.filter(d=>d.w===n).length;
    const inStock=w.filter(d=>d.sh&&d.sh.length);
    const hits=inStock.filter(d=>d.mx!=null&&Math.min(...d.sh.map(z=>z[1]))<=d.mx).length;
    const cheapest=inStock.reduce((s,d)=>s+Math.min(...d.sh.map(z=>z[1])),0);
    return kpiHTML([
      ["","Wanted", w.length.toLocaleString()],
      ["ord","Priority", byw(2)],
      ["dup","Grail", byw(3)],
      ["buy","In stock now", inStock.length, "at a shop the page tracks"],
      ["own","Under your ceiling", hits, "a tracked shop is at or below the most you said you would pay"],
      

      ["","Cheapest all in", inStock.length?priv(cheapest):"—", "buying every one of them at the lowest tracked price"]
    ]);
  }
  

  if(v==="badge" && typeof badgeState==="function"){
    const st=badgeState(), got=st.list.filter(x=>x.earned);
    const tier=t=>got.filter(x=>x.def.tier===t).length;
    const near=st.list.filter(x=>!x.earned&&!x.def.manual&&x.pct>0).sort((a,b)=>b.pct-a.pct)[0];
    return kpiHTML([
      ["own","Earned", got.length.toLocaleString(), "badges you have reached"],
      ["","On offer", st.list.length.toLocaleString(), "badges the engine knows about"],
      ["","Gold and above", (tier("gold")+tier("platinum")+tier("signature")).toLocaleString()],
      ["ord", near?("Closest · "+near.def.name):"Closest",
        near?Math.round(near.pct*100)+"%":"—",
        near?(near.value.toLocaleString()+" of "+near.target.toLocaleString()+" "+near.def.unit)
            :"nothing in progress"]
    ]);
  }
  return null;
}



function emptyState(){
  const v=curView(), fs=activeFilters(), hasQ=(q||"").trim().length>0;
  const where = brand==="__all" ? "your collection" : brand;
  const act=(label,id)=>`<button type="button" class="btn sec" data-empty="${id}">${label}</button>`;
  let icon='<circle cx="12" cy="12" r="9" stroke-dasharray="3 4"/>', head="", body="", acts=[];
  if(hasQ){
    icon='<circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/>';
    head=`No car called \u201c${esc(q.trim())}\u201d`;
    body=`Nothing in ${esc(where)} matches that name or number.`;
    acts.push(act("Clear the search","q"));
    if(fs.filter(f=>f.k!=="q").length) acts.push(act("Clear the filters too","all"));
    if(brand!=="__all") acts.push(act("Look in every catalogue","brand"));
    

    if(typeof AUTH === "object" && AUTH) acts.push(act("Tell us it is missing","missing"));
  } else if(v==="want"){
    icon='<path d="M12 20s-7.5-4.6-7.5-9.4A4.1 4.1 0 0 1 12 8a4.1 4.1 0 0 1 7.5 2.6C19.5 15.4 12 20 12 20z"/>';
    head="Nothing on the want list yet";
    body="Tap the heart on any card and it turns up here, with the shops that have it and what they are asking.";
    acts.push(act("Browse the directory","dir"));
  } else if(v==="own"){
    icon='<path d="M4 10l8-5 8 5v9a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1z"/><path d="M8 20v-6h8v6"/>';
    head=`Nothing from ${esc(where)} on the shelf`;
    body="Tap the tick on a card to put a car in the garage. It takes one press, and the price and condition can go in later.";
    acts.push(act("Browse the directory","dir"));
    if(brand!=="__all") acts.push(act("Look at every catalogue","brand"));
  } else if(v==="order"){
    head="Nothing on the way";
    body="Cars marked as ordered appear here until you mark them as arrived.";
    acts.push(act("Browse the directory","dir"));
  } else if(v==="dupe"){
    head="No duplicates";
    body="Every car you own is a single copy. Raise a car's quantity in its panel and it shows up here.";
  } else if(v==="buy"){
    head="Nothing in stock";
    body=`No shop the page tracks has a ${brand==="__all"?"car":esc(brand)+" car"} on the shelf under these filters.`;
    if(fs.length) acts.push(act("Clear the filters","all"));
  } else if(v==="exc"){
    head="Nothing in this group";
    body="No car matches the group you picked under the filters you have set.";
    if(fs.length) acts.push(act("Clear the filters","all"));
  } else if(fs.filter(f=>f.k!=="q").length){
    head="No car matches those filters";
    body=fs.filter(f=>f.k!=="q").map(f=>f.v).join(" \u00b7 ");
    acts.push(act("Clear the filters","all"));
  } else {
    head="Nothing here";
    body="There is nothing on file for this combination.";
  }
  return `<div class="es"><span class="es-ic"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7">${icon}</svg></span>
    <h3>${head}</h3><p>${body}</p>${acts.length?`<div class="es-acts">${acts.join("")}</div>`:""}</div>`;
}
 
