const SHEETS=[];


const DIALOGS = [];
function dialogTop(){ return DIALOGS.length ? DIALOGS[DIALOGS.length - 1] : null; }


function focusablesIn(el){
  if(!el) return [];
  return [...el.querySelectorAll(
    'a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),'
    + 'textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')]
    .filter(n => !n.hidden && n.offsetParent !== null);
}
function dialogOpen(panel, onClose, opener){
  if(!panel) return;
   
  const at = DIALOGS.findIndex(d => d.panel === panel);
  if(at > -1) DIALOGS.splice(at, 1);
  DIALOGS.push({panel, onClose, opener: opener || document.activeElement});
  document.body.style.overflow = "hidden";
  

  const f = focusablesIn(panel);
  try{ (f.length ? f[0] : panel).focus({preventScroll:true}); }
  catch(e){ try{ panel.focus(); }catch(_){} }
}
function dialogClose(panel){
  const at = DIALOGS.findIndex(d => d.panel === panel);
  if(at < 0) return false;
  const d = DIALOGS.splice(at, 1)[0];
  if(!DIALOGS.length && !drawerOpen && !$("#mask").classList.contains("on"))
    document.body.style.overflow = "";
  

  try{ if(d.opener && document.contains(d.opener)) d.opener.focus({preventScroll:true}); }catch(e){}
  return true;
}


addEventListener("keydown", e => {
  if(e.key !== "Tab") return;
  const top = dialogTop(); if(!top) return;
  const f = focusablesIn(top.panel);
  if(!f.length){ e.preventDefault(); try{ top.panel.focus(); }catch(_){} return; }
  const first = f[0], last = f[f.length - 1];
  const here = document.activeElement;
  if(!top.panel.contains(here)){ e.preventDefault(); (e.shiftKey ? last : first).focus(); return; }
  if(e.shiftKey && here === first){ e.preventDefault(); last.focus(); }
  else if(!e.shiftKey && here === last){ e.preventDefault(); first.focus(); }
}, true);

function openSheet(id){
  const m=document.getElementById(id+"mask");
  m.hidden=false;
  const sh=document.getElementById(id+"sheet");
  const btn=document.getElementById(id+"btn");
  if(btn) btn.setAttribute("aria-expanded","true");
  dialogOpen(sh || m, () => closeSheet(id), btn || document.activeElement);
}
function closeSheet(id){
  const m=document.getElementById(id+"mask");
  if(!m||m.hidden) return;
  m.hidden=true;
  const sh=document.getElementById(id+"sheet");
  dialogClose(sh || m);
  const btn=document.getElementById(id+"btn"); if(btn) btn.setAttribute("aria-expanded","false");
}


let FILTER_DEFAULTS=null;
function noteFilterDefaults(){ if(!FILTER_DEFAULTS) FILTER_DEFAULTS={line, brand}; }
function activeFilters(){
  const out=[];
  const defLine = !!(FILTER_DEFAULTS && brand===FILTER_DEFAULTS.brand && line===FILTER_DEFAULTS.line);
  if(defLine){
  } else if(line!=="__all"){
    const sel=document.getElementById("line");
    const opt=[...sel.options].find(o=>o.value===line);
    out.push({k:"line",lab:taxLabelHere("br","Range"),v:opt?opt.text.replace(/\s+—.*$/,""):line,clear:()=>{line="__all";sel.value="__all";}});
  }
  

  for(const k of [...segPick])
    out.push({k:"seg:"+k, lab:taxLabelHere("seg","Segment"),
              v:k==="__none"?"Not placed":segName(k),
              clear:()=>{ segPick.delete(k); fillSegments(); }});
  for(const k of [...attrPick])
    out.push({k:"attr:"+k, lab:"Classification", v:attrName(k),
              clear:()=>{ attrPick.delete(k); fillAttrs(); }});
  

  for(const k of collects)
    out.push({k:"col:"+k, lab:"Collection", v:collectionLabel(k),
              clear:()=>{ collects.delete(k); }});
  if(marque) out.push({k:"marque",lab:"Marque",v:marque,clear:()=>{marque="";document.getElementById("marque").value="";}});
  

  for(const k of scalePick)
    out.push({k:"scale:"+k, lab:"Scale",
              v: k==="__none" ? "not stated" : k==="__box" ? "box scale" : k.replace("/",":"),
              clear:()=>{ scalePick.delete(k); fillScales(); }});
  if(relOnly) out.push({k:"rel",lab:"",v:"Released only",clear:()=>{relOnly=false;$("#relonly").classList.remove("on");}});
  if(chaseOnly) out.push({k:"chase",lab:"",v:"Chases you hold",clear:()=>{chaseOnly=false;$("#chaseonly").classList.remove("on");}});
  if(chaseMade) out.push({k:"chasex",lab:"",v:"Has a chase",clear:()=>{chaseMade=false;$("#chaseexists").classList.remove("on");}});
  if(chaseHunt) out.push({k:"chaseh",lab:"",v:"Chase still to find",clear:()=>{chaseHunt=false;$("#chasehunt").classList.remove("on");}});
  if(collabOnly) out.push({k:"collab",lab:"",v:"Collaborations",clear:()=>{collabOnly=false;$("#collabonly").classList.remove("on");}});
  

  for(const k of [...rarPick])
    out.push({k:"rar:"+k, lab:"Rarity",
              v: k === "__none" ? "Not established" : k,
              clear:()=>{ rarPick.delete(k); fillRarity(); }});
  if(noPreowned) out.push({k:"nopre",lab:"",v:"Pre-owned hidden",clear:()=>{noPreowned=false;$("#nopreowned").classList.remove("on");}});
  if(noBoxes) out.push({k:"nobox",lab:"",v:"Boxes hidden",clear:()=>{noBoxes=false;$("#noboxes").classList.remove("on");}});
  if(typeof showCanc!=="undefined"&&showCanc) out.push({k:"canc",lab:"",v:"Cancelled shown",clear:()=>{showCanc=false;$("#canctoggle").classList.remove("on");}});
  if((q||"").trim()) out.push({k:"q",lab:"Search",v:q.trim(),clear:()=>{q="";$("#q").value="";$("#qclear").classList.remove("on");}});
  return out;
}
function paintFilters(){
  const fs=activeFilters();
  const n=fs.filter(f=>f.k!=="q").length;
  const b=document.getElementById("filtn");
  if(b){ b.textContent=n; b.hidden=!n; }
  document.getElementById("filterbtn").classList.toggle("on", n>0);
  const box=document.getElementById("activef");
  if(box){
    box.innerHTML = fs.length<1 ? "" :
      fs.map((f,i)=>`<button type="button" class="fchip" data-f="${i}" aria-label="Remove filter ${esc(f.v)}">${f.lab?`<b>${esc(f.lab)}</b>`:""}${esc(f.v)}<span aria-hidden="true">×</span></button>`).join("")
      + (fs.length>1?`<button type="button" class="fchip clearall" data-f="-1">Clear all</button>`:"");
  }
  const sl=document.getElementById("sortlbl");
  if(sl){
    const o=[...document.getElementById("sort").options].find(o=>o.value===sort);
    sl.textContent=o?o.text.replace(/,.*$/,"").replace(/ A–Z$/,"").trim():"Sort";
  }
}
document.getElementById("activef").onclick=e=>{
  const b=e.target.closest(".fchip"); if(!b) return;
  const i=+b.dataset.f, fs=activeFilters();
  if(i<0) fs.forEach(f=>f.clear()); else if(fs[i]) fs[i].clear();
  recount(); render(); paintFilters();
};


function drawBrandSheet(){
  const host = document.getElementById("brandlist"); if(!host) return;
  const qv = (document.getElementById("brandq")||{}).value || "";
  const want = qv.trim().toLowerCase();
  const have={}, all={};
  for(const d of DATA){
    if(!isRelease(d)) continue;
    for(const bn of brandsOf(d)){ all[bn]=(all[bn]||0)+1; if(isOwned(d)) have[bn]=(have[bn]||0)+1; }
  }
  const hit = b => !want || b.toLowerCase().includes(want);
  

  

  const houseOf = b => { const G = (typeof BRAND_GROUP === "object" && BRAND_GROUP) ? BRAND_GROUP : {};
    if(G[b]) return G[b];
    for(const k in G) if(G[k] === b) return b;
    return null; };
  const gkey = (b, n) => { const g = houseOf(b);
    if(!g) return [n[b]||0, b];
    let top = 0; for(const x of BRANDS) if(houseOf(x) === g) top = Math.max(top, n[x]||0);
    return [top, g, n[b]||0, b]; };
  const bySize = n => (a, c) => {
    const ka = gkey(a, n), kc = gkey(c, n);
    return (kc[0]||0) - (ka[0]||0)
        || String(ka[1]).localeCompare(String(kc[1]))
        || (kc[2]||0) - (ka[2]||0)
        || String(ka[3]||a).localeCompare(String(kc[3]||c));
  };
  const mine = BRANDS.filter(b => (have[b]||0) > 0 && hit(b)).sort(bySize(have));
  const rest = BRANDS.filter(b => !(have[b]||0) && hit(b)).sort(bySize(all));
  

  let oAll = 0, oHave = 0;
  for(const d of DATA){ if(!isRelease(d)) continue; oAll++; if(isOwned(d)) oHave++; }
  const pick = (b, label, h, a) =>
      `<button type="button" class="brandpick${b===brand?" on":""}" data-b="${esc(b)}">`
    + `<b>${esc(label)}</b><i>${h.toLocaleString()}/${a.toLocaleString()}</i></button>`;
  

  const groupOf = b => (typeof BRAND_GROUP === "object" && BRAND_GROUP) ? BRAND_GROUP[b] : null;
   
  const childrenOf = b => { const G = (typeof BRAND_GROUP === "object" && BRAND_GROUP) ? BRAND_GROUP : {};
    return Object.keys(G).filter(k => G[k] === b); };
  const pins = pinnedBrands();
  const row = b => { const g = groupOf(b);
    const kids = g ? [] : childrenOf(b);
    const tag = g ? g : (kids.length ? "also " + kids.join(" and ") : "");
    const up = pins.indexOf(b) > -1;
    

    return `<div class="brandrow">`
      + `<button type="button" class="brandpick${b===brand?" on":""}" data-b="${esc(b)}">`
      + `<b>${esc(b)}${tag?`<span class="bgroup">${esc(tag)}</span>`:""}</b>`
      + `<i>${(have[b]||0).toLocaleString()}/${(all[b]||0).toLocaleString()}</i></button>`
      + `<button type="button" class="pinbtn${up?" on":""}" data-pin="${esc(b)}"`
      + ` aria-pressed="${up}"`
      + ` title="${up?"On the row. Tap to take it off.":"Pin it to the row."}">`
      + `<span aria-hidden="true">${up?"\u25C6":"\u25C7"}</span>`
      + `<span class="vh">${up?"Pinned to the row":"Pin to the row"}</span></button>`
      + `</div>`; };
  host.innerHTML =
    (hit("overall") || hit("everything") || !want
      ? `<div class="brandgrid">${pick("__all", "Overall collection", oHave, oAll)}</div>` : "")
    + (mine.length ? `<p class="fl">What you collect</p><div class="brandgrid">${mine.map(row).join("")}</div>` : "")
    + (rest.length ? `<p class="fl">${mine.length?"Everything else":"Every catalogue"}</p><div class="brandgrid">${rest.map(row).join("")}</div>` : "")
    + (!mine.length && !rest.length ? `<p class="hint">No catalogue here matches that.</p>` : "");
}
