const SRC_WORD = {
  OFFICIAL_MANUFACTURER:"the manufacturer", OFFICIAL_CATALOGUE:"the maker's own catalogue",
  OFFICIAL_ANNOUNCEMENT:"an official announcement", DISTRIBUTOR:"an authorised distributor",
  SPECIALIST_RETAILER:"a specialist retailer", COLLECTOR_DATABASE:"a collector database",
  AUCTION_RESULT:"an auction result", MARKETPLACE_SOLD:"completed sales",
  MARKETPLACE_LISTING:"a marketplace listing", COMMUNITY_SOURCE:"a community source",
  OWNER_RECORD:"your own records"
};


var RARWHY = null, _rwGot = null;
function rarWhyLoad(){
  if(_rwGot) return _rwGot;
  const loading = (document.readyState === "loading");
  if(typeof RARWHY_URL === "string" && RARWHY_URL){
    _rwGot = fetch(RARWHY_URL, {cache:"force-cache"})
      .then(r => r.ok ? r.json() : {}).then(j => { RARWHY = j || {}; }).catch(() => { RARWHY = {}; });
    return _rwGot;
  }
  const el = document.getElementById("raritydata");
  if(!el && loading) return Promise.resolve();
  RARWHY = {};
  if(el){ try{ RARWHY = JSON.parse(el.textContent) || {}; }catch(e){} }
  _rwGot = Promise.resolve();
  return _rwGot;
}
async function openWhy(n){
  const d = byNum.get(n); if(!d) return;
  let r = rarityOf(d); if(!r) return;
  openSheet("why");
  const _t0 = document.getElementById("whytitle");
  if(_t0) _t0.textContent = (d.t ? String(d.t) : n);
  document.getElementById("whybody").innerHTML = "<p class='whyhead'>Reading the evidence\u2026</p>";
  await rarWhyLoad();
  const w = (RARWHY && RARWHY[n]) || {};
  r = Object.assign({}, r, w);
  const ev = (r.e || []).map(x => `
    <div class="evrow"><b>${esc(x.w)}</b>
      <i>${esc(SRC_WORD[x.t] || "a source")}${x.n ? " — " + esc(x.n) : ""}</i>
      ${x.x ? `<div class="evnote">${esc(x.x)}</div>` : ""}
    </div>`).join("");
  const conflict = r.k ? `<div class="whywarn"><b>Sources disagree.</b> ${
      r.k.map(c => esc(c.source)).join(" and ")} give different production figures for this
      release. The more authoritative one leads and the disagreement is kept rather than
      tidied away, which is why the confidence above is lower than it would otherwise be.</div>` : "";
  const capped = (r.q === 0) ? `<div class="whywarn">Nobody has published how many of these were
      made. The score rests on what kind of release it is and how it was sold, which can
      say a great deal and cannot say a number, so it is held below the top of the
      scale however special the release.</div>` : "";
  document.getElementById("whybody").innerHTML =
    `<p class="whyhead"><b>${r.s} / 100 &middot; ${esc(r.b)}</b>, confidence ${esc(r.c.toLowerCase())}.<br>
     This is how scarce the release itself appears to be: how few were made, and how
     narrowly they were sold. It is <b>not</b> what one is worth, <b>not</b> how many
     MYMINI164 members own one, and <b>not</b> how badly people want one. Those are three
     separate figures and they sit in their own rows on the card.</p>
     ${ev || "<p class='whyhead'>No evidence recorded.</p>"}
     ${conflict}${capped}
     <p class="whyhead" style="margin:14px 0 0">Worked out by <code>${esc(r.a || "rarity-v1")}</code>.
     If the method changes, every score is recalculated rather than left as it was.</p>`;
}
