function railChrome(box){
  const onBtn=box.querySelector("button.on");
  if(onBtn && box.scrollWidth>box.clientWidth+4){
    const l=onBtn.offsetLeft, r=l+onBtn.offsetWidth, pad=14;
    if(l-pad < box.scrollLeft || r+pad > box.scrollLeft+box.clientWidth)
      box.scrollLeft = Math.max(0, l-pad);
  }
  const fade=()=>{ box.classList.toggle("fade-l", box.scrollLeft>4);
                   box.classList.toggle("fade-r", box.scrollLeft+box.clientWidth < box.scrollWidth-4); };
  fade(); box.onscroll=fade;
}



function syncStickyTops(){
  const bar=document.querySelector(".appbar"), rail=document.querySelector(".railwrap");
  if(!bar||!rail) return;
  const top=Math.round(bar.getBoundingClientRect().height);
  const st=document.documentElement.style;
  st.setProperty("--rail-top", top+"px");
  st.setProperty("--toolbar-top", (top+Math.round(rail.getBoundingClientRect().height))+"px");
}
