function pinnedBrands(){
  let want = null;
  try{ const raw = localStorage.getItem(PIN_KEY); if(raw) want = JSON.parse(raw); }catch(e){}
  if(!Array.isArray(want)) want = PIN_DEFAULT;
  

  if(!Array.isArray(BRANDS) || !BRANDS.length) return want.slice();
  

  const keep = want.filter(b => BRANDS.indexOf(b) > -1);
  if(keep.length) return keep;
  return PIN_DEFAULT.filter(b => BRANDS.indexOf(b) > -1);
}
function setPinnedBrands(list){
  savePref(PIN_KEY, JSON.stringify(list));
  paintBrands();
  if(document.getElementById("brandsheet") &&
     document.getElementById("brandsheet").classList.contains("on")) drawBrandSheet();
}
function togglePin(b){
  if(!b || b === "__all" || BRANDS.indexOf(b) < 0) return;
  const now = pinnedBrands();
  const at = now.indexOf(b);
  if(at > -1){
    

    if(now.length === 1){ toast("Keep at least one catalogue on the row"); return; }
    now.splice(at, 1);
    toast(b + " taken off the row");
  } else {
    now.push(b);
    toast(b + " pinned to the row");
  }
  setPinnedBrands(now);
}

function paintBrands(){
  const box=$("#brands"); if(!box) return;
  refreshBrands();
  

  

  

  const _have={}, _all={}, _coming={};
  for(const d of DATA){
    if(!isRelease(d)) continue;
    const bs=brandsOf(d), got=isOwned(d), coming=isIncoming(d);
    _all["__all"]=(_all["__all"]||0)+1;
    if(got) _have["__all"]=(_have["__all"]||0)+1;
    if(coming) _coming["__all"]=(_coming["__all"]||0)+1;
    for(const bn of bs){
      _all[bn]=(_all[bn]||0)+1;
      if(got) _have[bn]=(_have[bn]||0)+1;
      if(coming) _coming[bn]=(_coming[bn]||0)+1;
    }
  }
  const rail = pinnedBrands().slice();
  

  if(brand !== "__all" && rail.indexOf(brand) < 0) rail.push(brand);
  const hidden = BRANDS.length - rail.length;
  const opts=["__all",...rail];
  box.innerHTML=opts.map(b=>{
    

    const name = b==="__all" ? (innerWidth<=760 ? "Overall" : "Overall collection") : b;
    const on = b===brand;
    

    

    const have=_have[b]||0, all=_all[b]||0, coming=_coming[b]||0;
    const what=`${have.toLocaleString()} of ${all.toLocaleString()} owned`
      + (coming ? `, ${coming.toLocaleString()} more on the way` : "");
    return `<button type="button" aria-pressed="${on}" data-b="${esc(b)}" class="${on?"on":""}"`
      + ` title="${b==="__all"?"Every car on file, each counted once \u2014 "+what:esc(b)+" \u2014 "+what}">`
      + `${esc(name)} <i>${have}/${all}</i></button>`;
  }).join("")
  + (hidden > 0
     ? `<button type="button" class="brandmore" id="brandmore"`
       + ` title="Every catalogue on file, with a search box">`
       + `More <i>+${hidden}</i></button>`
     : "");
  railChrome(box);
  const note=$("#brandnote");
  if(note){
    const shared=DATA.filter(d=>brandsOf(d).length>1).length;
    note.textContent = brand==="__all"
      ? (shared ? `${shared} of these are in two catalogues and are counted once here.` : "")
      : (shared ? `Brand totals overlap: ${shared} release${shared===1?" is":"s are"} in two catalogues, counted once in the overall figure.` : "");
  }
}
