let imgFails=0, warned=false;
document.addEventListener("error", e=>{
  const im=e.target;
  if(!im || im.tagName!=="IMG" || im.dataset.failed) return;
  const wasLocal = im.src.indexOf("garage_images/")>-1;
  if(wasLocal){
    
    
    
    const step=(+im.dataset.ext||0)+1;
    if(step<IMG_EXT.length){
      im.dataset.ext=step;
      im.src=im.src.replace(/\.[^.\/]+$/,"."+IMG_EXT[step]);
      return;
    }
    if(im.dataset.remote){ const r=im.dataset.remote; im.removeAttribute("data-remote"); im.src=r; return; }
  }
  im.dataset.failed="1";
  
  
  if(!wasLocal || im.dataset.remote) imgFails++;
  const ph=im.parentNode;
  if(ph && ph.classList.contains("ph")) ph.innerHTML='<div class="noimg">photo unavailable</div>';
  

  else if(ph && ph.classList.contains("big")){
    ph.classList.add("noshot");
    ph.innerHTML='<div class="noimg">photo unavailable \u2014 it is hosted by the shop and needs an internet connection</div>';
  }
  if(imgFails>=25 && !warned){
    warned=true;
    document.getElementById("imgwarn").style.display="block";
  }
}, true);



const STORE_KEY = "minigt-garage-v1";


const EDIT_FIELDS = ["o","q","c","pd","v","x","xn","cp","bcs","w","mx","src","note","t","br","m","b","user","bs","cb"];

let EDITS = {patches:{}, added:[], removed:[]};
let dirty = false, editMode = false;
let DB = null, syncState = "local";      
const writeQ = new Map();                

const byNum = new Map();
function reindex(){
  byNum.clear(); DATA.forEach(d=>byNum.set(d.n,d)); clearSearchCache();
  

  if(typeof forgetCollections === "function") forgetCollections();
  if(typeof forget164 === "function") forget164();
  

  if(typeof applyDetail === "function") applyDetail(DATA);
  

  if(typeof forgetPhotoIndex === "function") forgetPhotoIndex();
}
reindex();


let _BASE = null;
function baseRows(){
  if(!_BASE) _BASE = (typeof CAT_SRC === "string") ? unpackCat(JSON.parse(CAT_SRC))
                                                   : JSON.parse(JSON.stringify(DATA));
  return _BASE;
}



function num(v){ const n = typeof v === "number" ? v : parseFloat(v); return Number.isFinite(n) ? n : null; }
function normaliseEdits(raw){
  const out = {patches:{}, added:[], removed:[]};
  if(!raw || typeof raw !== "object" || Array.isArray(raw)) return out;
  const P = raw.patches;
  if(P && typeof P === "object" && !Array.isArray(P)){
    for(const [n, body] of Object.entries(P)){
      if(typeof n !== "string" || !n) continue;
      if(!body || typeof body !== "object" || Array.isArray(body)) continue;
      out.patches[n] = body;
    }
  }
  if(Array.isArray(raw.added))
    for(const row of raw.added)
      if(row && typeof row === "object" && !Array.isArray(row) && typeof row.n === "string" && row.n)
        out.added.push(row);
  if(Array.isArray(raw.removed))
    out.removed = raw.removed.filter(n => typeof n === "string" && n);
  return out;
}

 
function loadStore(){
  try{ const raw=localStorage.getItem(STORE_KEY); if(raw) return JSON.parse(raw); }catch(e){}
  return null;
}
function saveStore(){
  try{ localStorage.setItem(STORE_KEY, JSON.stringify(EDITS)); }catch(e){}
}



const FS_DB = "minigt-garage-fs", FS_KEY = "handle";
let FSH = null;                       
let fsState = "off";                  
let fsTimer = null, fsWriting = false, fsAgain = false;
const fsSupported = () => typeof window.showSaveFilePicker === "function";

function idb(){
  return new Promise((res, rej) => {
    const r = indexedDB.open(FS_DB, 1);
    r.onupgradeneeded = () => r.result.createObjectStore("h");
    r.onsuccess = () => res(r.result);
    r.onerror = () => rej(r.error);
  });
}
async function idbGet(){
  try{
    const db = await idb();
    return await new Promise((res) => {
      const rq = db.transaction("h").objectStore("h").get(FS_KEY);
      rq.onsuccess = () => res(rq.result || null);
      rq.onerror = () => res(null);
    });
  }catch(e){ return null; }
}
async function idbPut(v){
  try{
    const db = await idb();
    await new Promise((res) => {
      const rq = db.transaction("h", "readwrite").objectStore("h").put(v, FS_KEY);
      rq.onsuccess = rq.onerror = () => res();
    });
  }catch(e){}
}

function fsPayload(){
  const owned = DATA.filter(d => d.o === 1).length;
  return JSON.stringify({
    savedAt: new Date().toISOString(),
    note: "Written automatically by the MYMINI164 page. Keep it next to the HTML.",
    owned, edits: EDITS
  }, null, 1);
}



async function fsFlush(){
  if(!FSH || fsWriting) { if(FSH) fsAgain = true; return; }
  fsWriting = true;
  try{
    const w = await FSH.createWritable();
    await w.write(fsPayload());
    await w.close();
    setSync("file");
  }catch(e){
    setSync(e && e.name === "NotAllowedError" ? "fileask" : "error");
  }finally{
    fsWriting = false;
    if(fsAgain){ fsAgain = false; fsTimer = setTimeout(fsFlush, 150); }
  }
}
function fsQueue(){
  if(!FSH) return;
  clearTimeout(fsTimer);
  fsTimer = setTimeout(fsFlush, 400);
}

async function fsPick(){
  if(!fsSupported()){ alert("This browser cannot write files directly. Use Backup instead."); return; }
  try{
    const h = await window.showSaveFilePicker({
      suggestedName: "MYMINI164_collection.json",
      types: [{description: "MYMINI164 collection data", accept: {"application/json": [".json"]}}]
    });
    FSH = h; await idbPut(h);
    await fsFlush();
    const as = document.getElementById("autosave");
    if(as){ as.textContent = "Auto-save ✓"; as.title = "Every change is being written to your save file"; }
  }catch(e){
    

    if(e && e.name !== "AbortError")
      alert("This browser would not let the page choose a file (" + (e.name||"refused") +
            "). Your changes are still kept in this browser, and Backup still works.");
  }
}



function fsMerge(fileEdits){
  fileEdits = normaliseEdits(fileEdits);
  EDITS = normaliseEdits(EDITS);
  const out = {patches:{}, added:[], removed:[]};
  for(const [n,p] of Object.entries(EDITS.patches || {})) out.patches[n] = Object.assign({}, p);
  for(const [n,p] of Object.entries(fileEdits.patches || {}))
    out.patches[n] = Object.assign(out.patches[n] || {}, p);
  const seen = new Set();
  for(const r of [...(fileEdits.added||[]), ...(EDITS.added||[])]){
    if(!r || !r.n || seen.has(r.n)) continue;
    seen.add(r.n); out.added.push(r);
  }
  out.removed = [...new Set([...(fileEdits.removed||[]), ...(EDITS.removed||[])])];
  EDITS = out;
}

async function fsBoot(){
  if(DB) return;                       
  if(!fsSupported()){ fsState = "unsupported"; return; }
  const h = await idbGet();
  if(!h) return;
  let perm = "prompt";
  try{ perm = await h.queryPermission({mode:"readwrite"}); }catch(e){ perm = "prompt"; }
  if(perm !== "granted"){ FSH = h; fsState = "needs-permission"; setSync("fileask"); return; }
  FSH = h;
  try{
    const txt = await (await h.getFile()).text();
    if(txt.trim()){
      const j = JSON.parse(txt);
      fsMerge(j.edits);
      DATA.length = 0; baseRows().forEach(d => DATA.push(JSON.parse(JSON.stringify(d))));
      reindex(); applyEdits(); saveStore(); markDirty(); recount(); render();
    }
    setSync("file");
  }catch(e){ setSync("fileask"); }
}

 
async function fsReconnect(){
  if(!FSH) return fsPick();
  try{
    const p = await FSH.requestPermission({mode:"readwrite"});
    if(p !== "granted") return;
    const txt = await (await FSH.getFile()).text();
    if(txt.trim()){
      const j = JSON.parse(txt);
      fsMerge(j.edits);
      DATA.length = 0; baseRows().forEach(d => DATA.push(JSON.parse(JSON.stringify(d))));
      reindex(); applyEdits(); saveStore(); markDirty(); recount(); render();
    }
    setSync("file");
    fsFlush();
  }catch(e){ setSync("fileask"); }
}

 


function ensureRow(n, body){
  if(EDITS.removed.includes(n)) EDITS.removed = EDITS.removed.filter(x=>x!==n);
  let d = byNum.get(n);
  if(!d){
    d = Object.assign({n, b:(String(n).match(/(\d+)/)||[0,0])[1]|0, t:n, s:1, k:0, o:0,
                       c:"", m:"Other", i:"", v:0, e:1, pd:null, sh:[], q:0, user:1}, body||{});
    DATA.push(d); byNum.set(n, d);
  }
  return d;
}
let BASE_BY = null, _appliedOnce = false;
function applyEdits(){
  

  const _first = !_appliedOnce;
  _appliedOnce = true;
  if(_first && !EDITS.added.length && !EDITS.removed.length
     && !Object.keys(EDITS.patches).length){
    DATA.forEach(d=>{ if(d.q==null) d.q = d.o?1:0; });
    reindex();
    return;
  }
  if(!BASE_BY) BASE_BY = new Map(baseRows().map(b=>[b.n,b]));
  for(let i=DATA.length-1;i>=0;i--) if(!BASE_BY.has(DATA[i].n)) DATA.splice(i,1);
  for(const d of DATA){
    const b = BASE_BY.get(d.n); if(!b) continue;
    for(const k of EDIT_FIELDS){
      const v = b[k];
      if(v === undefined) delete d[k];
      else d[k] = (v && typeof v === "object") ? JSON.parse(JSON.stringify(v)) : v;
    }
  }
  reindex();
  

  for(const row of EDITS.added){ if(row && row.n) ensureRow(row.n, row); }
  for(const [n,p] of Object.entries(EDITS.patches)){ const d=byNum.get(n); if(d) Object.assign(d,p); }
  for(const n of EDITS.removed){
    const i=DATA.findIndex(d=>d.n===n && d.user);
    if(i>-1){ byNum.delete(n); DATA.splice(i,1); }
  }
  DATA.forEach(d=>{ if(d.q==null) d.q = d.o?1:0; });
  reindex();
}

 
function bodyOf(d){
  const b={};
  for(const k of EDIT_FIELDS) if(d[k]!==undefined && d[k]!==null && d[k]!=="") b[k]=d[k];
  if(d.o===0) b.o=0;
  return b;
}


const unsaved = new Set();
let _unsaidT = null;
function sayUnsaved(){
  clearTimeout(_unsaidT);
  

  _unsaidT = setTimeout(() => {
    const n = unsaved.size;
    if(!n) return;
    

    toast(n === 1
      ? "One change has not been saved. It is still on screen and will be sent again when the connection is back."
      : n + " changes have not been saved. They are still on screen and will be sent again when the connection is back.",
      "bad", 0);
  }, 900);
}
function retryUnsaved(){
  if(!unsaved.size) return;
  for(const n of [...unsaved]) queueWrite(n);
}
addEventListener("online", retryUnsaved);

async function writeOnce(n){
  const d = byNum.get(n);
  if(!d) await DB.doc("cars/" + n).delete();
  else   await DB.doc("cars/" + n).set(bodyOf(d));
}
function queueWrite(n){
  if(!DB) return;
  const prev = writeQ.get(n) || Promise.resolve();
  const next = prev.then(async ()=>{
    let last = null;
    for(let attempt = 0; attempt < 3; attempt++){
      if(attempt) await new Promise(r => setTimeout(r, 400 * attempt));
      try{
        await writeOnce(n);
        unsaved.delete(n);
        

        setSync(unsaved.size ? "error" : "synced");
        if(unsaved.size) retryUnsaved();
        else { clearTimeout(_unsaidT); untoast(); }
        return;
      }catch(e){
        last = e;
        

        if(e && (e.code === "invalid_argument" || /row-level security|not allowed|forbidden/i.test(e.message || "")))
          break;
      }
    }
    if(last && last.code === "invalid_argument"){ setSync("readonly"); return; }
    unsaved.add(n);
    setSync("error");
    sayUnsaved();
  }).catch(()=>{});
  writeQ.set(n, next);
  return next;
}

function patch(n, changes){
  clearSearchCache();       
  const d = byNum.get(n); if(!d) return;
  Object.assign(d, changes);
  if(d.user){
    const row = EDITS.added.find(r=>r.n===n);
    if(row) Object.assign(row, changes);
  }else{
    EDITS.patches[n] = Object.assign(EDITS.patches[n]||{}, changes);
  }
  if(DB) queueWrite(n); else { dirty = true; saveStore(); fsQueue(); }
  markDirty();
}

function markDirty(){
  const n = Object.keys(EDITS.patches).length + EDITS.added.length + EDITS.removed.length;
  const b = document.getElementById("dirtyn");
  if(b) b.textContent = n ? "("+n+")" : "";
  paintSync();
}

 
function setSync(s){ syncState = s; paintSync(); }
function paintSync(){
  const el = document.getElementById("syncdot"); if(!el) return;
  const map = {
    local:     ["", "Changes are kept in this browser. Turn on Auto-save to keep them in a file."],
    file:      ["●", "Saved. Every change is written straight to your save file."],
    fileask:   ["●", "Click to reconnect your save file — a page cannot reopen it on its own."],
    connecting:["…", "Connecting to your collection…"],
    synced:    ["●", "Saved. Your phone and your laptop see the same collection."],
    readonly:  ["◌", "You can look but not change this copy."],
    error:     ["!", "Could not save. Still on screen, not stored."]
  };
  let [dot, tip] = map[syncState] || map.local;
  

  if(syncState === "error" && typeof unsaved === "object" && unsaved && unsaved.size)
    tip = (unsaved.size === 1 ? "One change is" : unsaved.size + " changes are")
        + " still on screen but not stored. They will be sent again when the connection"
        + " is back.";
  el.textContent = dot; el.title = tip;
  el.style.color = (syncState==="synced"||syncState==="file") ? "var(--own)"
                 : syncState==="fileask" ? "var(--gold)"
                 : syncState==="error" ? "var(--danger,#ef4444)"
                 : "var(--tx3)";
  el.style.display = dot ? "" : "none";
  el.style.cursor = syncState==="fileask" ? "pointer" : "";
}

 


function copiesOf(d){
  

  if(Array.isArray(d.cp)) return d.cp.filter(c => c && typeof c === "object");
  if(!d.o) return [];
  

  const COPY_CAP = 999;
  const qn=num(d.q);
  const n=Math.min(COPY_CAP, Math.max(1, (qn!=null && qn>0) ? Math.floor(qn) : 1)), out=[];
  for(let i=0;i<n;i++) out.push({c:d.c||"", x:(i===0?(d.x||""):"")});
  return out;
}


function qtyOf(d){
  if(!d.o) return 0;
  if(Array.isArray(d.cp)){ let n=0; for(const c of d.cp) if(c&&typeof c==="object") n++; return n; }
  const qn=num(d.q);
  return Math.min(999, Math.max(1, (qn!=null&&qn>0)?Math.floor(qn):1));
}
function valOf(d){
  const rv=num(d.v)||0;
  if(!d.o) return 0;
  if(!Array.isArray(d.cp)) return rv*qtyOf(d);       
  let t=0;
  for(const c of d.cp){ if(!c||typeof c!=="object") continue;
    const cv=(c.v!=null)?num(c.v):null; t+=(cv!=null?cv:rv); }
  return t;
}


function paidOf(d){
  

  if(!d.o) return 0;
  const rowPd=num(d.pd);
  if(!Array.isArray(d.cp)) return rowPd||0;          
  let t=0, usedRow=false;
  for(const c of d.cp){
    if(!c||typeof c!=="object") continue;
    const cp = c.pd!=null ? num(c.pd) : null;
    if(cp!=null) t+=cp;
    else if(!usedRow && rowPd){ t+=rowPd; usedRow=true; }
  }
  return t;
}
function paidGaps(d){
  const cps=copiesOf(d); let n=0, usedRow=false;
  const rowPd=num(d.pd);
  for(const c of cps){
    if(c && c.pd!=null && num(c.pd)!=null) continue;
    if(!usedRow && rowPd){ usedRow=true; continue; }
    n++;
  }
  return n;
}
function tallies(d){
  const cps=copiesOf(d), cond={}, tag={};
  for(const c of cps){
    const k=(c.c||"").toUpperCase()||"UNRECORDED";
    cond[k]=(cond[k]||0)+1;
    for(const x of (c.x||"").split(",").map(s=>s.trim()).filter(Boolean))
      tag[x]=(tag[x]||0)+1;
  }
  return {n:cps.length, cond, tag};
}

 
function editBar(d){
  if(!editMode) return "";
  const q = qtyOf(d);
  return `<div class="editbar" data-n="${d.n}">
    <button data-a="own" class="${d.o===1?"on":""}" title="Owned">${d.o===1?"✓ owned":d.o===2?"on the way":"not owned"}</button>
    <button data-a="minus" ${q<=0?"disabled":""}>−</button>
    <span class="lab" style="min-width:2.4em;text-align:center;font-weight:700">${q}</span>
    <button data-a="plus">+</button>
    <span class="sp"></span>
    <button data-a="more">Edit…</button>
    ${d.user?`<button data-a="del" style="color:var(--danger,#b91c1c)">Delete</button>`:""}
  </div>`;
}

 
const LINE_OPTS = () => [...new Set(DATA.map(d=>d.br))].sort();
function formHTML(d){
  const v = (k,f)=> d && d[k]!=null ? String(d[k]) : (f||"");
  const isNew = !d;
  return `<div class="body"><button class="close" id="x">Close</button>
    <h2 style="margin:0 0 4px">${isNew?"Add a car":"Edit "+d.n}</h2>
    <p class="sub" style="margin:0 0 6px">${isNew
      ? "For anything the catalogue does not list. The number you give is how the photo is found, so name your photo file after it."
      : "Saved as soon as you press Save."}</p>
    <div class="form">
      <label>Catalogue number</label><input id="f_n" value="${v("n")}" ${isNew?"":"disabled"} placeholder="MGT01234">
      <div class="hint">A photo named after this number, e.g. ${v("n","MGT01234")}.jpg, shows up automatically on the desktop copy.</div>
      <label>Model</label><input id="f_t" value="${esc(v("t"))}" placeholder="Porsche 911 GT3 Shark Blue">
      <!-- The range defaults to where you are standing, not to the maker this app
           started life tracking. Adding a Tomica while browsing Tomica should not
           offer to file it under Mini GT. -->
      <label>Range</label><input id="f_br" list="lines" value="${v("br", line !== "__all" && !isCross(line) ? line : (brand !== "__all" ? brand : ""))}">
      <datalist id="lines">${LINE_OPTS().map(b=>`<option value="${b}">`).join("")}</datalist>
      <label>Catalogue</label>
      <div class="catpick" id="f_bs">${BRANDS.map(b=>{
          const on = d ? brandsOf(d).indexOf(b)>-1 : (brand!=="__all" && b===brand);
          return `<label class="cb"><input type="checkbox" value="${esc(b)}" ${on?"checked":""}> ${esc(b)}</label>`;
        }).join("")}<input id="f_bsx" placeholder="or another maker" value="${esc((d?brandsOf(d):[]).filter(x=>BRANDS.indexOf(x)<0).join(", "))}"></div>
      <div class="hint">A car sold under two names is still one car. Tick every catalogue it belongs to and it appears in each one while staying a single record.</div>
      <label>Collaboration</label><input id="f_cb" value="${esc(v("cb"))}" placeholder="Tarmac Works × Schuco">
      <label>Marque</label><input id="f_m" value="${v("m")}" placeholder="Porsche">
      <label>Status</label><select id="f_o">
        <option value="1" ${!d||d.o===1?"selected":""}>In your collection</option>
        <option value="2" ${d&&d.o===2?"selected":""}>On the way</option>
        <option value="0" ${d&&!d.o?"selected":""}>Not yours</option>
      </select>
      <label>Quantity</label><input id="f_q" type="number" min="0" step="1" value="${d?Math.max(1,qtyOf(d)||1):1}">
      <label>Condition</label><select id="f_c">
        ${["","SEALED","MINT","GOOD","FAIR"].map(c=>`<option ${d&&d.c===c?"selected":""} value="${c}">${c||"not recorded"}</option>`).join("")}
      </select>
      <label>Price paid, this purchase</label><input id="f_pd" type="number" min="0" step="0.01" value="${d&&d.pd!=null?d.pd:""}" placeholder="0.00">
      <label>Market value, each</label><input id="f_v" type="number" min="0" step="0.01" value="${d&&d.v?d.v:""}" placeholder="0.00">
      <label>Variant</label><input id="f_x" value="${v("x")}" placeholder="chase, blister, error…">
    </div>
    <div class="formrow">
      <button class="btn pri" id="f_save">${isNew?"Add to collection":"Save"}</button>
      ${!isNew?`<button class="btn sec" id="f_notown">Remove from collection</button>`:""}
      ${d&&d.user?`<button class="btn dan" id="f_del">Delete entirely</button>`:""}
      <button class="btn sec" id="f_cancel">Cancel</button>
    </div></div>`;
}

function openForm(d){
  $("#modal").innerHTML = formHTML(d);
  openModal();
  const g = id => document.getElementById(id);
  const readForm = () => ({
    t: g("f_t").value.trim(),
    

    br: g("f_br").value.trim() || "Other",
    m: g("f_m").value.trim() || "Other",
    o: +g("f_o").value,
    q: Math.max(0, parseInt(g("f_q").value||"1",10)),
    

    cp: (()=>{ const want=Math.max(0,parseInt(g("f_q").value||"1",10));
               const cps=(d?copiesOf(d):[]).slice();
               while(cps.length>want) cps.pop();
               while(cps.length<want) cps.push({c:(cps[0]&&cps[0].c)||g("f_c").value||"",x:""});
               return cps; })(),
    c: g("f_c").value,
    pd: g("f_pd").value===""?null:+g("f_pd").value,
    v: g("f_v").value===""?0:+g("f_v").value,
    x: g("f_x").value.trim()||undefined,
    bs: (()=>{
      const picked=[...g("f_bs").querySelectorAll("input[type=checkbox]:checked")].map(c=>c.value);
      const extra=g("f_bsx").value.split(",").map(t=>t.trim()).filter(Boolean);
      const all=[...new Set(picked.concat(extra))];
      

      if(all.length) return all;
      if(brand !== "__all") return [brand];
      const _br = g("f_br").value.trim();
      const _own = (typeof RANGE_OWNER === "object" && RANGE_OWNER) ? RANGE_OWNER[_br] : null;
      return [_own || _br || "Other"];
    })(),
    cb: g("f_cb").value.trim()||undefined
  });
  g("f_save").onclick = () => {
    const f = readForm();
    if(!f.t){ alert("Give the car a name."); return; }
    if(!d){
      const n = g("f_n").value.trim().toUpperCase();
      if(!n){ alert("Give it a catalogue number - it is how the photo is matched."); return; }
      if(!/^[A-Za-z0-9_.~:@+-]{1,60}$/.test(n)){ alert("Use letters, digits and - . _ only in a catalogue number."); return; }
      if(byNum.has(n)){ alert(n+" is already in the list. Search for it and edit it instead."); return; }
      const row = Object.assign({n, b:(n.match(/(\d+)/)||[0,0])[1]|0, s:1, k:0, i:"", e:1, sh:[], user:1}, f);
      if(!Array.isArray(row.bs) || !row.bs.length) row.bs = [row.br || "Other"];
      EDITS.added.push(row);
      ensureRow(n, row);
      if(DB) queueWrite(n); else { dirty=true; saveStore(); }
      markDirty();
    }else{
      patch(d.n, f);
    }
    closeModal(); recount(); render();
  };
  if(g("f_notown")) g("f_notown").onclick = () => {
    patch(d.n, {o:0, q:0, c:"", pd:null});
    closeModal(); recount(); render();
  };
  if(g("f_del")) g("f_del").onclick = () => {
    if(!confirm("Delete "+d.n+" from the list completely? This only removes cars you added yourself.")) return;
    removeUserRow(d.n);
    closeModal(); recount(); render();
  };
  g("f_cancel").onclick = closeModal;
  g("x").onclick = closeModal;
}

function removeUserRow(n){
  const i=DATA.findIndex(r=>r.n===n); if(i>-1) DATA.splice(i,1);
  byNum.delete(n);
  EDITS.added = EDITS.added.filter(r=>r.n!==n);
  if(!EDITS.removed.includes(n)) EDITS.removed.push(n);
  if(DB) queueWrite(n); else { dirty=true; saveStore(); }
  markDirty();
}

 


let DL = undefined;
async function download(name, text, type){
  if(DL === undefined){ try{ DL = await claude.use("downloads"); }catch(e){ DL = null; } }
  if(DL){
    try{ await DL.save({filename:name, data:text}); return true; }
    catch(e){ if(e && e.code==="not_granted") return false; }
  }
  const b = new Blob([text], {type: type||"application/json"});
  const u = URL.createObjectURL(b);
  const a = document.createElement("a");
  a.href = u; a.download = name; document.body.appendChild(a); a.click();
  setTimeout(()=>{ URL.revokeObjectURL(u); a.remove(); }, 400);
  return true;
}
 


function csvCell(v){
  if(v === null || v === undefined) return "";
  let t = String(v);
  

  if(/^[=+\-@\t\r]/.test(t)) t = "'" + t;
  return /[",\n\r]/.test(t) ? '"' + t.replace(/"/g, '""') + '"' : t;
}
const CSV_COLS = [
  ["Number",        d => d.n],
  ["Name",          d => d.t],
  

  ["Catalogues",    d => brandsOf(d).join(" | ")],
  ["Line",          d => d.br],
  ["Collaboration", d => d.cb || ""],
  ["Drive",         d => d.hand || ""],
  ["Marque",        d => d.m],
  ["Year",          d => d.yr || ""],
  ["Released",      d => d.xc ? "cancelled" : (d.s ? "yes" : "not yet")],
  ["Status",        d => d.o === 1 ? "owned" : d.o === 2 ? "on order" : "not owned"],
  ["Copies",        d => d.o ? qtyOf(d) : 0],
  ["Condition",     d => Object.entries(tallies(d).cond)
                           .map(([k, n]) => n > 1 ? k + " x" + n : k).join(", ")],
  ["Tags",          d => Object.keys(tallies(d).tag).join(", ")],
  ["Paid",          d => paidOf(d) ? paidOf(d).toFixed(2) : ""],
  ["Price is",      d => paidOf(d) ? (d.src === "RRP" ? "retail estimate" : "receipt") : ""],
  ["Bought from",   d => d.src && d.src !== "RRP" ? d.src : ""],
  

  ["Order",         d => d.ord ? (d.ord.noref ? d.ord.shop + " " + (d.ord.date || "")
                                                : d.ord.shop + " #" + d.ord.id) : ""],
  ["Ordered on",    d => d.ord ? d.ord.date : ""],
  ["Est value",     d => valOf(d) ? valOf(d).toFixed(2) : ""],
  ["In stock at",   d => cheapestShop(d) ? cheapestShop(d)[0] : ""],
  ["Best price",    d => cheapestShop(d) ? cheapestShop(d)[1].toFixed(2) : ""],
  ["Link",          d => cheapestShop(d) ? (cheapestShop(d)[2] || "") : ""],
  ["Shops in stock",d => (d.sh || []).length],
  ["Packaging",     d => (d.iss || []).map(i => i.s).filter(Boolean).join(", ")],
  ["Scale",         d => scaleOf(d).s || ""],
  ["Number on the box", d => d.pnum ? "No." + d.pnum : ""],
  ["Family",        d => d.fam || ""],
  ["Tuner or livery", d => d.tn || ""],
  ["Barcode",       d => d.jan || ""],
  ["Racing series", d => (d.ms && d.ms.series) || ""],
  ["Season",        d => (d.ms && d.ms.season) || ""],
  ["Constructor",   d => (d.ms && d.ms.builder) || ""],
  ["Chassis",       d => (d.ms && d.ms.chassis) || ""],
  ["Driver",        d => (d.ms && d.ms.driver) || ""],
  ["Crew",          d => (d.ms && (d.ms.crew || []).join(" / ")) || ""],
  ["Car number",    d => (d.ms && d.ms.no != null ? d.ms.no : "")],
  ["Race",          d => (d.ms && d.ms.event) || ""],
  ["Entered by",    d => (d.ms && d.ms.team) || ""],
  ["Race livery",   d => (d.ms && d.ms.livery) || ""],
  ["Result",        d => (d.ms && d.ms.result) || ""],
  ["At the event as", d => (d.ms && d.ms.role) || ""],
  ["Race read from the name", d => (d.ms && d.ms.read) ? "yes" : ""],
  ["Exclusive to",  d => d.ex ? (d.ex.c === "?" ? "market not recorded" : d.ex.c) : ""],
  ["Exclusive why", d => d.ex ? d.ex.w : ""],
  ["007 line",      d => d.bond ? "yes" : ""],
  ["Chase exists",  d => d.chase ? "yes" : ""],
  ["Part of a set", d => d.k ? "this row is the set box" : setsOf(d).map(x => x.n).join(", ")],
  ["Want",          d => d.w ? ["", "want", "priority", "grail"][d.w] : ""],
  ["Ceiling",       d => d.mx != null ? (+d.mx).toFixed(2) : ""],
  ["Your note",     d => d.note || ""]
];
function cheapestShop(d){
  const sh = d.sh || []; if(!sh.length) return null;
  return sh.reduce((lo, z) => z[1] < lo[1] ? z : lo, sh[0]);
}


function buildCSV(rows){
  const head = CSV_COLS.map(c => /^(Paid|Est value|Best price|Ceiling)$/.test(c[0])
                                 ? c[0] + " (GBP)" : c[0]);
  const out = [head.map(csvCell).join(",")];
  for(const d of rows){
    out.push(CSV_COLS.map(c => { try{ return csvCell(c[1](d)); }catch(e){ return ""; } }).join(","));
  }
   
  return "﻿" + out.join("\r\n") + "\r\n";
}
function csvName(){
  const tab = {all:"all", own:"owned", order:"on-order", buy:"in-stock", miss:"missing",
               dupe:"duplicates", want:"want-list", value:"value", stats:"stats",
               exc:"exclusives"}[view] || String(view);
  

  const bits = [ brand==="__all" ? "garage" : brand.toLowerCase().replace(/[^a-z0-9]+/g,"-"), tab ];
  if(view === "exc" && excGroup)
    bits.push(excGroup === "007" ? "007" : excGroup.toLowerCase().replace(/[^a-z0-9]+/g, "-"));
  if(line !== "__all") bits.push(String(line).toLowerCase().replace(/[^a-z0-9]+/g, "-"));
  if(marque) bits.push(marque.toLowerCase().replace(/[^a-z0-9]+/g, "-"));
  if(q) bits.push(q.toLowerCase().replace(/[^a-z0-9]+/g, "-").slice(0, 24));
  bits.push(new Date().toISOString().slice(0, 10));
  return bits.filter(Boolean).join("_") + ".csv";
}
async function exportCSV(){
  

  let rows = current;
  if(!rows || !rows.length) rows = DATA.filter(d => inLine(d) && !d.k && !d.xc);
  const btn = $("#exportcsv"), was = btn ? btn.textContent : "";
  if(btn){ btn.textContent = "..."; btn.disabled = true; }
  try{
    const okDone = await download(csvName(), buildCSV(rows), "text/csv;charset=utf-8");
    if(typeof toast==="function") toast(okDone===false
      ? "The browser would not save the file"
      : rows.length.toLocaleString()+" rows exported", okDone===false?"bad":"good");
    if(btn) btn.textContent = okDone === false ? "blocked" : rows.length + " rows";
  }catch(e){
    if(btn) btn.textContent = "failed";
  }
  setTimeout(() => { if(btn){ btn.textContent = was || "CSV"; btn.disabled = false; } }, 1800);
}
if($("#exportcsv")) $("#exportcsv").onclick = exportCSV;



async function exportEverything(){
  const mine = DATA.filter(d => d.o || d.w);
  await download("mymini164_collection_" + new Date().toISOString().slice(0,10) + ".csv",
                 buildCSV(mine), "text/csv;charset=utf-8");
  if(typeof saveChanges === "function"){ try{ await saveChanges(); }catch(e){} }
  if(typeof toast === "function")
    toast(mine.length.toLocaleString() + " cars exported, plus a backup file", "good");
}

async function saveChanges(){
  const owned = DATA.filter(d=>d.o).map(d=>({
    n:d.n, t:d.t, br:d.br, m:d.m, q:qtyOf(d), c:d.c||"", pd:d.pd, v:d.v, x:d.x||"", user:d.user?1:0
  }));
  

  const ledger = {patches:{}, added:[...EDITS.added], removed:[...EDITS.removed]};
  const BASEBY = new Map(baseRows().map(d=>[d.n, d]));
  for(const d of DATA){
    

    if(d.user){ if(!ledger.added.some(r=>r.n===d.n)) ledger.added.push(Object.assign({n:d.n}, bodyOf(d))); continue; }
    const b = BASEBY.get(d.n); if(!b) continue;
    const diff = {};
    

    const blank = x => x===undefined || x===null || x==="" || x===0;
    for(const k of EDIT_FIELDS){
      const now = d[k], was = b[k];
      if(blank(now) && blank(was)) continue;
      if(k==="q" && now === (d.o?1:0) && blank(was)) continue;
      if(JSON.stringify(now===undefined?null:now) !== JSON.stringify(was===undefined?null:was)) diff[k]=now;
    }
    if(Object.keys(diff).length) ledger.patches[d.n]=diff;
  }
  const out = {
    

    format: "mini164-collection",
    formatVersion: 1,
    savedAt: new Date().toISOString(),
    note: "A snapshot of your collection. Restore it with the Load button, or hand it to Claude.",
    

    totals: {models: owned.length, pieces: owned.reduce((s,r)=>s+r.q,0),
             value: +DATA.reduce((s,d)=>s+valOf(d),0).toFixed(2),
             paid: +totalPaidOwned(DATA).toFixed(2),
             pricedAtRetail: +totalRetailStandIn(DATA).toFixed(2)},
    edits: ledger, owned
  };
  const _ok = await download("collection.json", JSON.stringify(out,null,1));
  dirty = false; markDirty();
   
  if(typeof toast==="function") toast(_ok===false
    ? "The browser would not save the backup"
    : "Backup saved \u2014 "+owned.length+" cars, "+out.totals.pieces+" pieces", _ok===false?"bad":"good");
}


function looksLikeBackup(j){
  if(!j || typeof j !== "object" || Array.isArray(j)) return false;
  const e = j.edits;
  if(!e || typeof e !== "object" || Array.isArray(e)) return false;
  const shapeOK = (e.patches === undefined || (e.patches && typeof e.patches === "object" && !Array.isArray(e.patches)))
    && (e.added === undefined || Array.isArray(e.added))
    && (e.removed === undefined || Array.isArray(e.removed));
  if(!shapeOK) return false;
  

  const hasLedger = (e.patches && Object.keys(e.patches).length)
                 || (Array.isArray(e.added) && e.added.length)
                 || (Array.isArray(e.removed) && e.removed.length);
  const hasOwned = Array.isArray(j.owned);
  return !!(hasLedger || hasOwned || j.savedAt || j.format);
}
function countEdits(ed){
  const e = normaliseEdits(ed);
  return Object.keys(e.patches).length + e.added.length + e.removed.length;
}
function loadChanges(file){
  const r = new FileReader();
  r.onerror = () => alert("That file could not be read from disk.");
  r.onload = async () => {
    let j = null;
    try{ j = JSON.parse(r.result); }
    catch(e){
      alert("That file is not readable as JSON, so nothing has been changed.\n\n" + e.message);
      return;
    }
    if(!looksLikeBackup(j)){
      alert("That does not look like a collection.json saved from this page, so nothing has been changed.");
      return;
    }
    const incoming = countEdits(j.edits), mineNow = countEdits(EDITS);
    const ownedNow = DATA.filter(d=>d.o).length;
    if(mineNow){
      const okGo = confirm(
        "Restoring replaces what is on this page.\n\n" +
        "On the page now: " + ownedNow + " models, " + mineNow + " change" + (mineNow===1?"":"s") + ".\n" +
        "In the file: " + (Array.isArray(j.owned) ? j.owned.length : "an unknown number of") +
        " models, " + incoming + " change" + (incoming===1?"":"s") +
        (j.savedAt ? ", saved " + String(j.savedAt).slice(0,10) : "") + ".\n\n" +
        "Replace what is here?");
      if(!okGo) return;
    }
    try{
      EDITS = normaliseEdits(j.edits);
      DATA.length = 0; baseRows().forEach(d=>DATA.push(JSON.parse(JSON.stringify(d))));
      reindex(); applyEdits();
      if(DB){ for(const n of new Set([...Object.keys(EDITS.patches), ...EDITS.added.map(x=>x.n), ...EDITS.removed])) queueWrite(n); }
      else { saveStore(); fsQueue(); }
      markDirty(); recount(); render();
      if(typeof paintFilters==="function"){ paintFilters(); paintNav(); paintDrawerCard(); }
      toast("Restored \u2014 " + DATA.filter(d=>d.o).length + " cars marked as yours", "good");
    }catch(e){
      alert("That file could not be applied, so nothing has been changed.\n\n" + e.message);
    }
  };
  r.readAsText(file);
}

 
function setEditMode(on){
  editMode = on;
  document.getElementById("editmode").classList.toggle("on", on);
  ["addcar","savechanges","loadchanges","autosave"].forEach(id=>{
    const e=document.getElementById(id); if(e) e.style.display = on ? "" : "none";
  });
  

  const as = document.getElementById("autosave");
  if(as){
    if(on && (DB || !fsSupported())) as.style.display = "none";
    as.textContent = FSH ? "Auto-save ✓" : "Auto-save";
    as.title = FSH ? "Every change is being written to your save file"
                   : "Keep every change in a file on this computer";
  }
  render();
}
