document.addEventListener("click", e => {
  const bar = e.target.closest(".editbar");
  if(!bar) return;
  e.stopPropagation();
  const n = bar.dataset.n, a = e.target.dataset.a, d = byNum.get(n);
  if(!d || !a) return;
  if(a==="own")   patch(n, d.o ? {o:0,q:0} : {o:1,q:Math.max(1,d.q||1)});
  if(a==="plus")  patch(n, {q:qtyOf(d)+1, o:1});
  if(a==="minus"){ const q=Math.max(0,qtyOf(d)-1); patch(n,{q, o:q?1:0}); }
  if(a==="more")  return openForm(d);
  if(a==="del"){ if(!confirm("Delete "+n+"?")) return; removeUserRow(n); }
  recount(); render();
}, true);

