var _bArtId = 0;


const BADGE_FACE = {"series-half-1":"\u00bd", "series-3q-1":"\u00be"};
function badgeFace(def){
  if(def.manual) return null;                       
  if(BADGE_FACE[def.id] !== undefined) return BADGE_FACE[def.id];
  const t = def.target;
  if(!(t > 0)) return null;
  if(t >= 100000) return null;
  if(t >= 1000) return (t / 1000) + "K";
  return String(t);
}



function badgeArt(def, st, size){
  const t = BADGE_TIERS[def.tier] || BADGE_TIERS.steel;
  const en = BADGE_ENAMEL[def.cat] || BADGE_ENAMEL.size;
  const earned = !!(st && st.earned);
  const id = "bg" + (++_bArtId);
  const glyph = BADGE_GLYPHS[def.glyph] || BADGE_GLYPHS.car;
  const face = badgeFace(def);
  

  const _bw = face ? (face.length >= 4 ? 30 : face.length === 3 ? 27 : 24) : 0;
  

  const hex = def.cat !== "honours";

  

  const rimA = earned ? t.a : "#3a4150", rimB = earned ? t.b : "#20242c",
        rimE = earned ? t.e : "#4b5464";
  const faceA = earned ? "#2b3038" : "#191d24", faceB = earned ? "#0a0c10" : "#101318";
  const enC  = earned ? en.c : "#2a313c";
  const enInk = earned ? en.ink : "#78838f";
  const gl   = earned ? "#ffffff" : "#7b8598";

  

  const shape = hex
    ? '<polygon points="60,3 109.3,31.5 109.3,88.5 60,117 10.7,88.5 10.7,31.5"'
    : '<circle cx="60" cy="60" r="56"';
  const shapeIn = hex
    ? '<polygon points="60,14 100.4,37.3 100.4,82.7 60,106 19.6,82.7 19.6,37.3"'
    : '<circle cx="60" cy="60" r="46.5"';
  const dimples = hex
    ? [[60,10.5],[102.6,35.2],[102.6,84.8],[60,109.5],[17.4,84.8],[17.4,35.2]]
    : [];

  return '<svg class="bsvg" viewBox="0 0 120 120" width="' + (size||104) + '" height="' + (size||104) + '" '
   + 'role="img" aria-hidden="true" focusable="false">'
   + '<defs>'
   

   + '<linearGradient id="' + id + 'r" x1="0.18" y1="0" x2="0.82" y2="1">'
   +   '<stop offset="0" stop-color="' + rimE + '"/>'
   +   '<stop offset="0.28" stop-color="' + rimA + '"/>'
   +   '<stop offset="0.54" stop-color="' + rimB + '"/>'
   +   '<stop offset="0.78" stop-color="' + rimA + '"/>'
   +   '<stop offset="1" stop-color="' + rimE + '"/></linearGradient>'
   + '<radialGradient id="' + id + 'f" cx="0.34" cy="0.26" r="0.92">'
   +   '<stop offset="0" stop-color="' + faceA + '"/>'
   +   '<stop offset="1" stop-color="' + faceB + '"/></radialGradient>'
   + '<linearGradient id="' + id + 's" x1="0" y1="1" x2="0.6" y2="0">'
   +   '<stop offset="0" stop-color="#ffffff" stop-opacity="0"/>'
   +   '<stop offset="1" stop-color="#ffffff" stop-opacity="' + (earned ? "0.16" : "0.04") + '"/></linearGradient>'
   + '<clipPath id="' + id + 'c">' + shapeIn + '/></clipPath>'
   + '</defs>'
   + shape + ' fill="url(#' + id + 'r)"/>'
   + shape + ' fill="none" stroke="' + rimE + '" stroke-opacity="' + (earned ? "0.55" : "0.25") + '" stroke-width="1"/>'
   + shapeIn + ' fill="url(#' + id + 'f)"/>'
    
   + '<g clip-path="url(#' + id + 'c)">'
   +   '<polygon points="-6,92 126,26 126,52 -6,118" fill="url(#' + id + 's)"/>'
   + '</g>'
   + dimples.map(pt => '<circle cx="' + pt[0] + '" cy="' + pt[1] + '" r="2.3" fill="'
       + (earned ? "#0b0d11" : "#12151a") + '" opacity="0.8"/>').join("")
   + shapeIn + ' fill="none" stroke="#000000" stroke-opacity="0.45" stroke-width="1.4"/>'
   + (face
      ? '<g transform="translate(46 20) scale(1.17)" fill="none" stroke="' + gl + '" '
        + 'stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" '
        + 'opacity="' + (earned ? "0.95" : "0.5") + '">' + glyph + '</g>'
        + '<rect x="' + (60 - _bw) + '" y="62" width="' + (_bw * 2) + '" height="24" rx="12" '
        + 'fill="' + enC + '"/>'
        + '<rect x="' + (60 - _bw) + '" y="62" width="' + (_bw * 2) + '" height="24" rx="12" '
        + 'fill="none" stroke="#ffffff" stroke-opacity="' + (earned ? "0.32" : "0.1") + '" stroke-width="1"/>'
        + '<text x="60" y="79" text-anchor="middle" fill="' + enInk + '" '
        + 'font-family="\'JetBrains Mono\', ui-monospace, monospace" font-size="17" '
        + 'font-weight="700" letter-spacing="-0.5">' + esc(face) + '</text>'
      : '<circle cx="60" cy="60" r="27" fill="' + enC + '" opacity="' + (earned ? "0.92" : "1") + '"/>'
        + '<circle cx="60" cy="60" r="27" fill="none" stroke="#ffffff" stroke-opacity="'
        + (earned ? "0.3" : "0.08") + '" stroke-width="1"/>'
        + '<g transform="translate(36 36) scale(2)" fill="none" stroke="' + enInk + '" '
        + 'stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">' + glyph + '</g>')
   + '</svg>';
}



 
const BADGE_MIN_LINE = 12;


var _bctx = null, _bstate = null;
function clearBadgeCache(){ _bctx = null; _bstate = null; }



const BADGE_ACT_KEY = "m164-acts";
function badgeActs(){
  try{ const o = JSON.parse(localStorage.getItem(BADGE_ACT_KEY) || "{}");
       return (o && typeof o === "object") ? o : {}; }catch(e){ return {}; }
}
function badgeAct(key, value){
  const o = badgeActs();
  if(Array.isArray(o[key]) || value === undefined){
    const set = new Set(Array.isArray(o[key]) ? o[key] : []);
    if(value !== undefined) set.add(value);
    o[key] = [...set];
  } else if(typeof value === "string"){
    const set = new Set(Array.isArray(o[key]) ? o[key] : []); set.add(value); o[key] = [...set];
  } else {
    o[key] = (typeof o[key] === "number" ? o[key] : 0) + (value || 1);
  }
  try{ localStorage.setItem(BADGE_ACT_KEY, JSON.stringify(o)); }catch(e){}
  clearBadgeCache();
  if(typeof scheduleBadgeCheck === "function") scheduleBadgeCheck();
}


var BADGE_EXTRA = { subsAccepted:0, reportsAccepted:0, loaded:false };



var _bcat = null;
function badgeCatalogue(){
  if(_bcat && _bcat.n === DATA.length) return _bcat;
  const brandAll = new Map(), lineAll = new Map(), marqueAll = new Map();
  const tomRanges = new Set(), tomScales = new Set();
  let tomLV = 0;
  const bump = (m,k) => m.set(k, (m.get(k)||0)+1);
  for(let i=0;i<DATA.length;i++){
    const d = DATA[i];
    if(d.xc || d.k) continue;
    const bs = brandsOf(d);
    for(let j=0;j<bs.length;j++) bump(brandAll, bs[j]);
    if(d.br) bump(lineAll, d.br);
    if(d.m)  bump(marqueAll, d.m);
    

    if(bs.indexOf(BADGE_TOMICA) > -1){
      if(d.br) tomRanges.add(d.br);
      if(d.sc) tomScales.add(d.sc);
      if(BADGE_TOM_LV.indexOf(d.br) > -1) tomLV++;
    }
  }
  return _bcat = {n:DATA.length, brandAll, lineAll, marqueAll, tomRanges, tomScales, tomLV};
}

function badgeCtx(){
  if(_bctx) return _bctx;
  const cat = badgeCatalogue();
  const c = {
    owned:0, pieces:0, ordered:0, wanted:0, dupes:0, spares:0,
    brandOwned:new Map(), brandAll:cat.brandAll,
    lineOwned:new Map(), lineAll:cat.lineAll,
    marqueOwned:new Map(), marqueAll:cat.marqueAll,
    markets:new Set(), shops:new Set(), orders:new Set(),
    tomRanges:new Set(), tomScales:new Set(), tomLV:0,
    tomRangeAll:cat.tomRanges, tomScaleAll:cat.tomScales, tomLVAll:cat.tomLV,
    withCond:0, withNote:0, withPaid:0, ceilings:0,
    chases:0, customs:0, collabs:0, exclusives:0, bonds:0, sets:0,
    dates:[], datedOwned:0,
    rooms:0, scans:0, skins:0, exports:0
  };
  const bump = (m,k) => m.set(k, (m.get(k)||0)+1);
  for(let i=0;i<DATA.length;i++){
    const d = DATA[i];
    if(!isRelease(d)) continue;                     
    if(isIncoming(d)) c.ordered++;
    if(d.w > 0 && !d.o) c.wanted++;
    if(d.w > 0 && d.mx != null) c.ceilings++;
    

    if(!isOwned(d)) continue;
    c.owned++;
    const q = qtyOf(d);
    c.pieces += q;
    if(q > 1){ c.dupes++; c.spares += q - 1; }
    const bs = brandsOf(d);
    for(const b of bs) bump(c.brandOwned, b);
    if(d.br) bump(c.lineOwned, d.br);
    if(d.m)  bump(c.marqueOwned, d.m);
    if(bs.indexOf(BADGE_TOMICA) > -1){
      if(d.br) c.tomRanges.add(d.br);
      if(d.sc) c.tomScales.add(d.sc);
      if(BADGE_TOM_LV.indexOf(d.br) > -1) c.tomLV++;
    }
    if(d.ex && d.ex.c && d.ex.c !== "?") c.markets.add(d.ex.c);
    if(d.ex) c.exclusives++;
    if(d.bond) c.bonds++;
    if(d.src && d.src !== "RRP") c.shops.add(String(d.src).trim().toLowerCase());
    if(d.ord && d.ord.id) c.orders.add(d.ord.id);
    if(d.c) c.withCond++;
    if(d.note && String(d.note).trim()) c.withNote++;
    

    if(paidReceipt(d) > 0) c.withPaid++;
    if(d.chase) c.chases++;
    if(d.user) c.customs++;
    if(d.cb || d.collab) c.collabs++;
    const dt = d.ord && d.ord.date;
    if(/^\d{4}-\d{2}-\d{2}$/.test(dt || "")){ c.dates.push(dt); c.datedOwned++; }
  }
  c.dates.sort();
  

  c.datesComplete = c.owned > 0 && c.datedOwned === c.owned;
  const acts = badgeActs();
  c.scans   = typeof acts.scans === "number" ? acts.scans : 0;
  c.exports = typeof acts.exports === "number" ? acts.exports : 0;
  c.rooms   = Array.isArray(acts.rooms) ? acts.rooms.length : 0;
  c.skins   = Array.isArray(acts.skins) ? acts.skins.length : 0;
  c.brandsOwnedCount  = c.brandOwned.size;
  c.linesOwnedCount   = c.lineOwned.size;
  c.marquesOwnedCount = c.marqueOwned.size;
  

  c.lineDone = 0; c.lineBest = 0; c.lineHalf = 0; c.lineThreeQ = 0;
  c.lines = [];
  for(const [ln, all] of c.lineAll){
    if(all < BADGE_MIN_LINE) continue;
    const own = c.lineOwned.get(ln) || 0;
    const pct = own / all;
    c.lines.push({line:ln, own, all, pct});
    if(pct >= 1) c.lineDone++;
    if(pct >= 0.5) c.lineHalf++;
    if(pct >= 0.75) c.lineThreeQ++;
    if(pct > c.lineBest) c.lineBest = pct;
  }
  c.lines.sort((a,b) => b.pct - a.pct || b.all - a.all);
  c.subsAccepted    = BADGE_EXTRA.subsAccepted || 0;
  c.reportsAccepted = BADGE_EXTRA.reportsAccepted || 0;
  return _bctx = c;
}



const BADGE_CATS = [
  {id:"size",      name:"The collection", blurb:"How many different cars are standing on the shelf."},
  {id:"garage",    name:"The garage",     blurb:"Copies, orders and the counters you buy across."},
  {id:"range",     name:"Range",          blurb:"How widely the collection reaches."},
  {id:"series",    name:"Series",         blurb:"Finishing what a maker numbered."},
  {id:"catalogue", name:"Catalogues",     blurb:"Depth inside one maker's own range."},
  {id:"marque",    name:"Marques",        blurb:"The car makers themselves, not the model makers."},
  {id:"craft",     name:"Record keeping", blurb:"Looking after the record as well as the cars."},
  {id:"guild",     name:"Contribution",   blurb:"Catalogue work that somebody checked and accepted."},
  {id:"honours",   name:"Honours",        blurb:"Given by hand. The engine never awards these."}
];
const BADGE_CAT_NAME = {};
BADGE_CATS.forEach(c => BADGE_CAT_NAME[c.id] = c.name);

function badgeSlug(s){
  return String(s||"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"") || "x";
}
function badgeTierFor(step, steps){
  const t = ["steel","chrome","gold","platinum"];
  return t[Math.min(t.length-1, Math.round(step / Math.max(1, steps-1) * (t.length-1)))];
}

